INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p3-7', 'doc-14-nist-sp-800-53', '', 3, 'There may be references in this publication to other publications currently under development by NIST in accordance with its assigned statutory responsibilities. The information in this publication, including concepts, practices, and methodologies may be used by federal agencies even before the completion of such companion publications. Thus, until each publication is completed, current requirements, guidelines, and procedures, where they exist, remain operative. For planning and transition purposes, federa l agencies may wish to closely follow the development of these new publications by NIST.', 'kb-doc-14-nist-sp-800-53-p3-7', 0, 83, '14-nist-sp-800-53', 'retrieved', 'A148F3721BEA63505257F46A1114B749D2E078CF660E9C5DBDEE54D540DF4BC5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
