INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p3-8', 'doc-14-nist-sp-800-53', '', 3, 'Organizations are encouraged to review draft publications during the designated public comment periods and provide feedback to NIST. Many NIST publications, other than the ones noted above, are available at https://csrc.nist.gov/publications.', 'kb-doc-14-nist-sp-800-53-p3-8', 0, 31, '14-nist-sp-800-53', 'retrieved', '3C3E6429DA9FBF9A89AC356B155F52AECD27741BEDBAF531E6208D259FBB60FF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
