VALUES ('doc-14-nist-sp-800-53-p4-1', 'doc-14-nist-sp-800-53', '', 4, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ ii This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p4-1', 0, 25, '14-nist-sp-800-53', 'retrieved', 'E7E923670C76928193C1C7A416487B653B87F5802FD014A72F4B72231E025197', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
