VALUES ('doc-14-nist-sp-800-53-p8-1', 'doc-14-nist-sp-800-53', '', 8, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ vi This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p8-1', 0, 25, '14-nist-sp-800-53', 'retrieved', 'B9534F9B58182023D9E3D750613928D30A4115E97E8265C1C41418D09E6D6078', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
