VALUES ('doc-14-nist-sp-800-53-p9-1', 'doc-14-nist-sp-800-53', '', 9, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ vii This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p9-1', 0, 25, '14-nist-sp-800-53', 'retrieved', '437CEFE32FC71591C4464D39A2B199EE77F0F3364E35887083F48CFD769F4341', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
