VALUES ('doc-14-nist-sp-800-53-p9-3', 'doc-14-nist-sp-800-53', '', 9, 'NIST anticipates using these mappings and the gaps they identify to improve the control catalog.', 'kb-doc-14-nist-sp-800-53-p9-3', 0, 15, '14-nist-sp-800-53', 'retrieved', 'E570A6C68910990082EF4E943D63DB065E37C2BB00B9572E76F0A812FB6C5620', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
