VALUES ('doc-14-nist-sp-800-53-p10-1', 'doc-14-nist-sp-800-53', '', 10, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ viii This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p10-1', 0, 25, '14-nist-sp-800-53', 'retrieved', '0024B5313EFDD3BECBB3270DEE98A5536FF5981BFED29AE52C1CA2B82F950A02', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
