VALUES ('doc-14-nist-sp-800-53-p11-1', 'doc-14-nist-sp-800-53', '', 11, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ ix This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p11-1', 0, 25, '14-nist-sp-800-53', 'retrieved', 'CB844EF2258D02CAD10CF5EBFFF74884BBD29E6599EAF717D8C43831788D92C5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
