INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p12-2', 'doc-14-nist-sp-800-53', '', 12, 'CONTROL BASELINES The control baselines that have previously been included in NIST Special Publication 800-53 have been relocated to NIST Special Publication 800 -53B. SP 800- 53B contains security and privacy control baselines for federal information systems and organizations. It provides guidance for tailoring control baselines and for developing o verlays to support the security and privacy requirements of stakeholder s and their organizations.', 'kb-doc-14-nist-sp-800-53-p12-2', 0, 64, '14-nist-sp-800-53', 'retrieved', '63B583D277D1F09D1F2B952E4FD6B02522E596C27FFD1FD0B8B3FC2B77721BAF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
