VALUES ('doc-14-nist-sp-800-53-p12-3', 'doc-14-nist-sp-800-53', '', 12, 'CNSS Instruction 1253 provides control baselines and guidance for security categorization and security control selection for national security systems.', 'kb-doc-14-nist-sp-800-53-p12-3', 0, 19, '14-nist-sp-800-53', 'retrieved', 'A1F42086DD10B9B46B4F890285F4E33A1446B1CA5A401F8BCDFC61F4D5BE3B69', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
