INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p13-2', 'doc-14-nist-sp-800-53', '', 13, 'USE OF EXAMPLES IN THIS PUBLICATION Throughout this publication, examples are used to illustrate, clarify, or explain certain items in chapter sections, controls, and control enhancements. These examples are illustrative in nature and are not intended to limit or constrain the application of controls or control enhancements by organizations.', 'kb-doc-14-nist-sp-800-53-p13-2', 0, 49, '14-nist-sp-800-53', 'retrieved', '49BDFFAC36E7FD5BBB8044B2C226920F4EBBE039A86DF8841B54FC9AA9F4E1CB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
