INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p14-2', 'doc-14-nist-sp-800-53', '', 14, 'FEDERAL RECORDS MANAGEMENT COLLABORATION Federal records management processes have a nexus with certain information security and privacy requirements and controls. For example, records officers may be managing records retention, including when records will be deleted. Collaborating with records officers on the selection and implementation of security and privacy controls related to records management can support consistency and efficiency and ultimately strengthen the organization’s security and privacy posture.', 'kb-doc-14-nist-sp-800-53-p14-2', 0, 67, '14-nist-sp-800-53', 'retrieved', '3FE8A89AE3D0528C6DC769CC61BEA89E7555515615A46B2E113C83174308576E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
