INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p17-2', 'doc-14-nist-sp-800-53', '', 17, '• Removing control baselines and tailoring guidance from the publication and transferring the content to NIST SP 800-53B, Control Baselines for Information Systems and Organizations; • Clarifying the relationship between requirements and controls and the relationship between security and privacy controls; and • Incorporating new, state-of-the-practice controls (e.g., controls to support cyber resiliency, support secure systems design, and strengthen security and privacy governance and accountability) based on the latest threat intelligence and cyber-attack data.', 'kb-doc-14-nist-sp-800-53-p17-2', 0, 74, '14-nist-sp-800-53', 'retrieved', '4308947961A47ED779435C4D8F2D35683FB897BF2F28F25626F4B68F3FC154E4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
