VALUES ('doc-14-nist-sp-800-53-p18-1', 'doc-14-nist-sp-800-53', '', 18, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ xvi This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p18-1', 0, 25, '14-nist-sp-800-53', 'retrieved', 'EA0476066A909A074092E61781A3A8C6DBD04B2E8446BF4D44EDAE36C310AF28', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
