VALUES ('doc-14-nist-sp-800-53-p19-1', 'doc-14-nist-sp-800-53', '', 19, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ xvii This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p19-1', 0, 25, '14-nist-sp-800-53', 'retrieved', '2CD0E23E82D39E75332FA83782476BD630D16CD30D4FEB7DCC79F2481C84F3DF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
