INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p19-2', 'doc-14-nist-sp-800-53', '', 19, 'Errata This table contains changes that have been incorporated into SP 800-53, Revision 5. Errata updates can include corrections, clarifications, or other minor changes in the publication that are either editorial or substantive in nature. Any potential updates for this document that are not yet published in an errata update or revision— including additional issues and potential corrections— will be posted as they are identified; see the SP 800-53, Revision 5 publication details.', 'kb-doc-14-nist-sp-800-53-p19-2', 0, 73, '14-nist-sp-800-53', 'retrieved', '93427B2BEC7723C6A66800E7552C0132523E91928501705D1E36D794728C86FF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
