VALUES ('doc-14-nist-sp-800-53-p28-1', 'doc-14-nist-sp-800-53', '', 28, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER ONE PAGE 1 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p28-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '2FCD9B9E972F8FD34C613A1557D759E170D75DCCE6BBE1CBB9984B7B15A509BA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
