INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p28-5', 'doc-14-nist-sp-800-53', '', 28, '2 The term organization describes an entity of any size, complexity, or positioning within an organizational structure (e.g., a federal agency or, as appropriate, any of its operational elements).', 'kb-doc-14-nist-sp-800-53-p28-5', 0, 29, '14-nist-sp-800-53', 'retrieved', '8FB1CDD961AD4C7D438B92B0D9DFA47A48CE246563ADB6E4F14A9D36DA513C59', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
