VALUES ('doc-14-nist-sp-800-53-p28-6', 'doc-14-nist-sp-800-53', '', 28, '3 The two terms information security and security are used synonymously in this publication.', 'kb-doc-14-nist-sp-800-53-p28-6', 0, 14, '14-nist-sp-800-53', 'retrieved', '640CF8B43F0BCBC48A28BDD0807DE6CD44C9755B12150B980B21BE079676A66B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
