VALUES ('doc-14-nist-sp-800-53-p28-8', 'doc-14-nist-sp-800-53', '', 28, '5 Controls provide safeguards and countermeasures in systems security and privacy engineering processes to reduce risk during the system development life cycle.', 'kb-doc-14-nist-sp-800-53-p28-8', 0, 22, '14-nist-sp-800-53', 'retrieved', '7284FFAF32CCBF39AEA9AA76EA301AE95CA2DFAFA33359BBD08E48394863B48E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
