INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p28-10', 'doc-14-nist-sp-800-53', '', 28, '7 Security and privacy control effectiveness addresses the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting the designated security and privacy requirements [SP 800-53A].', 'kb-doc-14-nist-sp-800-53-p28-10', 0, 36, '14-nist-sp-800-53', 'retrieved', '1FEEB0DFAE0C158968AE4A070467CE580E9C3CD1917E2CF07BC5EA700B2828A0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
