INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p29-7', 'doc-14-nist-sp-800-53', '', 29, '9 This includes risk to critical infrastructure and key resources described in [HSPD-7].', 'kb-doc-14-nist-sp-800-53-p29-7', 0, 13, '14-nist-sp-800-53', 'retrieved', 'B2565689512A997EBA2E5F3489B7A62C69E7CFC6654034E5B999EBEDA8FF6740', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
