INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p29-8', 'doc-14-nist-sp-800-53', '', 29, '10 A federal information system is an information system used or operated by an agency, a contractor of an agency, or another organization on behalf of an agency.', 'kb-doc-14-nist-sp-800-53-p29-8', 0, 28, '14-nist-sp-800-53', 'retrieved', '92E920574E6BD09739040604F49461A1A3DF5BB6D7E57D2F0D6A0D776288B7CC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p29-9', 'doc-14-nist-sp-800-53', '', 29, '11 Information systems that have been designated as national security systems, as defined in 44 U.S.C., Section 3542, are not subject to the requirements in [FISMA]. However, the controls established in this publication may be selected for national security systems as otherwise required (e.g., the Privacy Act of 1974) or with the approval of federal officials exercising policy authority over such systems. [CNSSP 22] and [CNSSI 1253] provide guidance for national security systems. [DODI 8510.01] provides guidance for the Department of Defense.', 'kb-doc-14-nist-sp-800-53-p29-9', 0, 82, '14-nist-sp-800-53', 'retrieved', '424A1C111C09CDC608AECDD45BF65AAC184EFD45B147EFFFB383BD78AD93282B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p29-10', 'doc-14-nist-sp-800-53', '', 29, '12 While the controls established in this publication are mandatory for federal information systems and organizations, other organizations such as state, local, and tribal governments as well as private sector organizations are encouraged to consider using these guidelines, as appropriate. See [SP 800-53B] for federal control baselines.', 'kb-doc-14-nist-sp-800-53-p29-10', 0, 47, '14-nist-sp-800-53', 'retrieved', '0FC0ABAC6F7D37F4FE9C8309530637608EFAE672256ACCBF81287741DA2A5EB2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p30-1', 'doc-14-nist-sp-800-53', '', 30, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER ONE PAGE 3 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p30-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D00685280B2CB1D024557CFDFA38A7DE83911D4515900A9ABA581EE222A7DADD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p30-2', 'doc-14-nist-sp-800-53', '', 30, 'Finally, the controls are independent of the process employed to select those controls. The control selection process can be part of an organization-wide risk management process, a systems engineering process [SP 800-160-1],13 the Risk Management Framework [SP 800-37], the Cybersecurity Framework [NIST CSF], or the Privacy Framework [NIST PF].14 The control selection criteria can be guided and informed by many factors, including mission and business needs, stakeholder protection needs, threats, vulnerabilities, and requirements to comply with federal laws, executive orders, directives, regulations, policies, standards, and guidelines. The combination of a catalog of security and privacy controls and a risk-based control selection process can help organizations comply with stated security and privacy requirements, obtain adequate security for their information systems, and protect the privacy of individuals.', 'kb-doc-14-nist-sp-800-53-p30-2', 0, 125, '14-nist-sp-800-53', 'retrieved', 'CC27365DA57FFD321C9EBDE9B6A782559ADB0846F6D81F45081D696A6BF8AC95', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p30-3', 'doc-14-nist-sp-800-53', '', 30, '1.2 TARGET AUDIENCE This publication is intended to serve a diverse audience, including: • Individuals with system, information security, privacy, or risk management and oversight responsibilities, including authorizing officials, chief information officers, senior agency information security officers, and senior agency officials for privacy; • Individuals with system development responsibilities, including mission owners, program managers, system engineers, system security engineers, privacy engineers, hardware and software developers, system integrators, and acquisition or procurement officials; • Individuals with logistical or disposition-related responsibilities, including program managers, procurement officials, system integrators, and property managers; • Individuals with security and privacy implementation and operations responsibilities, including mission or business owners, system owners, information owners or stewards, system administrators, continuity planners, and system security or privacy officers; • Individuals with security and privacy assessment and monitoring responsibilities, including auditors, Inspectors General, system evaluators, control assessors, independent verifiers and validators, and analysts; and • Commercial entities, including industry partners, producing component products and systems, creating security and privacy technologies, or providing services or capabilities that support information security or privacy.', 'kb-doc-14-nist-sp-800-53-p30-3', 0, 172, '14-nist-sp-800-53', 'retrieved', '5A05024FA5A5ED49F77CFC3CC3B4F5591E8C77A9CE174275E1253B7D0D8D29A3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p30-4', 'doc-14-nist-sp-800-53', '', 30, '1.3 ORGANIZATIONAL RESPONSIBILITIES Managing security and privacy risks is a complex, multifaceted undertaking that requires: • Well-defined security and privacy requirements for systems and organizations; • The use of trustworthy information system components based on state-of-the-practice hardware, firmware, and software development and acquisition processes;', 'kb-doc-14-nist-sp-800-53-p30-4', 0, 44, '14-nist-sp-800-53', 'retrieved', 'B973C70DEA1BD49356D67D10AEAD1F601197A97806D5C082F01748E51EC7F62A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p30-5', 'doc-14-nist-sp-800-53', '', 30, '13 Risk management is an integral part of systems engineering, systems security engineering, and privacy engineering.', 'kb-doc-14-nist-sp-800-53-p30-5', 0, 16, '14-nist-sp-800-53', 'retrieved', '2D259562BEF6F3FFE086B8A2ABB9F7015441207CC28780220C1ABC46268C4EE3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p30-6', 'doc-14-nist-sp-800-53', '', 30, '14 [OMB A-130] requires federal agencies to implement the NIST Risk Management Framework for the selection of controls for federal information systems. [EO 13800] requires federal agencies to implement the NIST Framework for Improving Critical Infrastructure Cybersecurity to manage cybersecurity risk. The NIST frameworks are also available to nonfederal organizations as optional resources.', 'kb-doc-14-nist-sp-800-53-p30-6', 0, 53, '14-nist-sp-800-53', 'retrieved', 'F8F4968503DA1048F4F9E271226007482E23ED4A757618E472B37AA469A747F8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p31-1', 'doc-14-nist-sp-800-53', '', 31, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER ONE PAGE 4 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p31-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '43C99A2F695176CD03A2FA29DEB4EFB430EB5C1F23C3B3C5FB3881EA65576515', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p31-2', 'doc-14-nist-sp-800-53', '', 31, '• Rigorous security and privacy planning and system development life cycle management; • The application of system security and privacy engineering principles and practices to securely develop and integrate system components into information systems; • The employment of security and privacy practices that are properly documented and integrated into and supportive of the institutional and operational processes of organizations; and • Continuous monitoring of information systems and organizations to determine the ongoing effectiveness of controls, changes in information systems and environments of operation, and the state of security and privacy organization-wide.', 'kb-doc-14-nist-sp-800-53-p31-2', 0, 91, '14-nist-sp-800-53', 'retrieved', '77D3C4C244A5D69DA668C00D870E2A64BE772D0458D4E322B127FA7447814C69', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
