INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p32-7', 'doc-14-nist-sp-800-53', '', 32, '21 Authorizing officials or their designated representatives, by accepting the security and privacy plans, agree to the security and privacy controls proposed to meet the security and privacy requirements for organizations and systems.', 'kb-doc-14-nist-sp-800-53-p32-7', 0, 33, '14-nist-sp-800-53', 'retrieved', '8ACC7E4F7EC503A3A15415066FA91B719D2DB6E0AC3A928B8308002A03B9F2AF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
