VALUES ('doc-14-nist-sp-800-53-p33-1', 'doc-14-nist-sp-800-53', '', 33, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER ONE PAGE 6 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p33-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '89FDBF2962896E8CF87EFCFC295B7CFD6B51B30564557AB0B4D8D98174AF3A1C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
