INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p33-2', 'doc-14-nist-sp-800-53', '', 33, '• Chapter Two describes the fundamental concepts associated with security and privacy controls, including the structure of the controls, how the controls are organized in the consolidated catalog, control implementation approaches, the relationship between security and privacy controls, and trustworthiness and assurance.', 'kb-doc-14-nist-sp-800-53-p33-2', 0, 42, '14-nist-sp-800-53', 'retrieved', 'A087D6068A114898B5727C8CD32C26BBC2D36E04DAA68DB7A6AE3A2B2937E5CC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
