INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p33-3', 'doc-14-nist-sp-800-53', '', 33, '• Chapter Three provides a consolidated catalog of security and privacy controls including a discussion section to explain the purpose of each control and to provide useful information regarding control implementation and assessment, a list of related controls to show the relationships and dependencies among controls, and a list of references to supporting publications that may be helpful to organizations.', 'kb-doc-14-nist-sp-800-53-p33-3', 0, 60, '14-nist-sp-800-53', 'retrieved', 'BE6193735630AB571BD610B0A60594866D9A7578421B211F9F87779EBC540366', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
