VALUES ('doc-14-nist-sp-800-53-p33-4', 'doc-14-nist-sp-800-53', '', 33, '• References, Glossary, Acronyms, and Control Summaries provide additional information on the use of security and privacy controls.23', 'kb-doc-14-nist-sp-800-53-p33-4', 0, 18, '14-nist-sp-800-53', 'retrieved', '0253F18D882EE86DA617D933245438D4C77A8D8CE061B165F14513A12CE71CC5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
