INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p33-5', 'doc-14-nist-sp-800-53', '', 33, '23 Unless otherwise stated, all references to NIST publications refer to the most recent version of those publications.', 'kb-doc-14-nist-sp-800-53-p33-5', 0, 18, '14-nist-sp-800-53', 'retrieved', '8A3F298D6657BB48C745956AC1308729CF37F16BCD9D9F52F5F845536419F082', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
