INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p35-3', 'doc-14-nist-sp-800-53', '', 35, '2.2 CONTROL STRUCTURE AND ORGANIZATION Security and privacy controls described in this publication have a well-defined organization and structure. For ease of use in the security and privacy control selection and specification process, controls are organized into 20 families.25 Each family contains controls that are related to the specific topic of the family. A two-character identifier uniquely identifies each control family (e.g., PS for Personnel Security). Security and privacy controls may involve aspects of policy, oversight, supervision, manual processes, and automated mechanisms that are implemented by systems or actions by individuals. Table 1 lists the security and privacy control families and their associated family identifiers.', 'kb-doc-14-nist-sp-800-53-p35-3', 0, 105, '14-nist-sp-800-53', 'retrieved', '093F20897E7D18A9A47924A7284998A21C593660AB88E48A2E373550DCD529AD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p35-4', 'doc-14-nist-sp-800-53', '', 35, 'TABLE 1: SECURITY AND PRIVACY CONTROL FAMILIES ID FAMILY ID FAMILY AC Access Control PE Physical and Environmental Protection AT Awareness and Training PL Planning AU Audit and Accountability PM Program Management CA Assessment, Authorization, and Monitoring PS Personnel Security CM Configuration Management PT PII Processing and Transparency CP Contingency Planning RA Risk Assessment IA Identification and Authentication SA System and Services Acquisition IR Incident Response SC System and Communications Protection MA Maintenance SI System and Information Integrity MP Media Protection SR Supply Chain Risk Management', 'kb-doc-14-nist-sp-800-53-p35-4', 0, 86, '14-nist-sp-800-53', 'retrieved', '32102A533A418F2969F63A0810214C6E34AFF0C4262AFC743C6EE3EDBE8C44EE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
