INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p35-7', 'doc-14-nist-sp-800-53', '', 35, 'The Program Management (PM), PII Processing and Transparency (PT), and Supply Chain Risk Management (SR) families address enterprise-level program management, privacy, and supply chain risk considerations pertaining to federal mandates emergent since [FIPS 200].', 'kb-doc-14-nist-sp-800-53-p35-7', 0, 34, '14-nist-sp-800-53', 'retrieved', 'E297D244E96FBD111FD0646F692E093A3E09E2AD222258E2F9B1AD4C07B694A1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
