INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p36-2', 'doc-14-nist-sp-800-53', '', 36, 'selection and implementation of control enhancements always requires the selection and implementation of the base control.', 'kb-doc-14-nist-sp-800-53-p36-2', 0, 16, '14-nist-sp-800-53', 'retrieved', '2A3E8A1E33288620F8F50381D8227F398E8AB5B35D58B18A379BF403A74AA4B1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
