VALUES ('doc-14-nist-sp-800-53-p36-13', 'doc-14-nist-sp-800-53', '', 36, 'Base Control Organization-defined Parameter Control Enhancement Sources for additional information related to the control Organization-defined Parameter Control Identifier Control Name', 'kb-doc-14-nist-sp-800-53-p36-13', 0, 20, '14-nist-sp-800-53', 'retrieved', '5FC159F7680C70477486E49C50CE18203D112C09DAB9BD23CC6B4AB77962F949', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
