VALUES ('doc-14-nist-sp-800-53-p37-1', 'doc-14-nist-sp-800-53', '', 37, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER TWO PAGE 10 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p37-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'A961E3D212D848B59C93D90F75AEE4A791F220605064CF800C6F6C24AF09094A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
