INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p37-2', 'doc-14-nist-sp-800-53', '', 37, 'flexibility to implement the controls selected in whatever manner that satisfies organizational mission or business needs consistent with law, regulation, and policy.', 'kb-doc-14-nist-sp-800-53-p37-2', 0, 22, '14-nist-sp-800-53', 'retrieved', 'D6FF2B7C558B7A2A7FA1847F53E034D9E89C58595D2B87115EA073473804C384', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
