INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p37-9', 'doc-14-nist-sp-800-53', '', 37, '26 References are provided to assist organizations in understanding and implementing the security and privacy controls and are not intended to be inclusive or complete.', 'kb-doc-14-nist-sp-800-53-p37-9', 0, 25, '14-nist-sp-800-53', 'retrieved', '2AAE4540950445E60497D33C7F86A9FBE9E1A4F49015256A1913D6CF79FBECBE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
