VALUES ('doc-14-nist-sp-800-53-p41-1', 'doc-14-nist-sp-800-53', '', 41, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER TWO PAGE 14 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p41-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'B988F2B6684C56B5058636F55872325D7E40CBB224CD237ECF78054663A778C4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
