INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p41-10', 'doc-14-nist-sp-800-53', '', 41, '30 [SP 800-160-1] provides guidance on systems security engineering and the application of security design principles to achieve trustworthy systems.', 'kb-doc-14-nist-sp-800-53-p41-10', 0, 20, '14-nist-sp-800-53', 'retrieved', '03F362291BD268CE200D77D544219CB30930389F09B174B8AA051855C3690B96', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
