INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p42-2', 'doc-14-nist-sp-800-53', '', 42, 'Organizations can select assurance-related controls to define system development activities, generate evidence about the functionality and behavior of the system, and trace the evidence to the system elements that provide such functionality or exhibit such behavior. The evidence is used to obtain a degree of confidence that the system satisfies the stated security and privacy requirements while supporting the organization’s mission and business functions. Assurance- related controls are identified in the control summary tables in Appendix C.', 'kb-doc-14-nist-sp-800-53-p42-2', 0, 77, '14-nist-sp-800-53', 'retrieved', '23129AC8F8AE56B44AB84C2378138796770BBEF33E05C378AE512E57BD99F04F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p42-3', 'doc-14-nist-sp-800-53', '', 42, 'EVIDENCE OF CONTROL IMPLEMENTATION During control selection and implementation, it is important for organizations to consider the evidence (e.g., artifacts, documentation) that will be needed to support current and future control assessments. Such assessments help determine whether the controls are implemented correctly, operating as intended, and satisfying security and privacy policies— thus, providing essential information for senior leaders to make informed risk-based decisions.', 'kb-doc-14-nist-sp-800-53-p42-3', 0, 63, '14-nist-sp-800-53', 'retrieved', '5B0B413FD48135C1E4AB31EE35AD6F5682FCD3E464F9B0B8A5A0689734263052', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
