INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p47-5', 'doc-14-nist-sp-800-53', '', 47, 'Control Enhancements: (1) ACCOUNT MANAGEMENT | AUTOMATED SYSTEM ACCOUNT MANAGEMENT Support the management of system accounts using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p47-5', 0, 21, '14-nist-sp-800-53', 'retrieved', '6CED3F38052D3B439E41E4B9ABE0054C72E5874284FAB020E2F9D04ECE035136', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p47-6', 'doc-14-nist-sp-800-53', '', 47, 'Discussion: Automated system account management includes using automated mechanisms to create, enable, modify, disable, and remove accounts; notify account managers when an account is created, enabled, modified, disabled, or removed, or when users are terminated or transferred; monitor system account usage; and report atypical system account usage.', 'kb-doc-14-nist-sp-800-53-p47-6', 0, 47, '14-nist-sp-800-53', 'retrieved', '51D2D68B0A58860DD335A709A85C7E363D4D7DFF7F2AC776CE5B426F19971A88', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p47-7', 'doc-14-nist-sp-800-53', '', 47, 'Automated mechanisms can include internal system functions and email, telephonic, and text messaging notifications.', 'kb-doc-14-nist-sp-800-53-p47-7', 0, 14, '14-nist-sp-800-53', 'retrieved', 'E57303156A2F78A638A53C99A1535D8E986DF567CFC17308398E49E246C6178C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
