INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p47-9', 'doc-14-nist-sp-800-53', '', 47, '(2) ACCOUNT MANAGEMENT | AUTOMATED TEMPORARY AND EMERGENCY ACCOUNT MANAGEMENT Automatically [Selection: remove; disable] temporary and emergency accounts after [Assignment: organization-defined time period for each type of account].', 'kb-doc-14-nist-sp-800-53-p47-9', 0, 28, '14-nist-sp-800-53', 'retrieved', '01553BCD5B43D54D4FB2394FDA9CA43C5FD5185499C8DA769A516E58DF0207C0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
