INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p47-10', 'doc-14-nist-sp-800-53', '', 47, 'Discussion: Management of temporary and emergency accounts includes the removal or disabling of such accounts automatically after a predefined time period rather than at the convenience of the system administrator. Automatic removal or disabling of accounts provides a more consistent implementation.', 'kb-doc-14-nist-sp-800-53-p47-10', 0, 41, '14-nist-sp-800-53', 'retrieved', '196C9E77DEBE69FB0F76AD936F9796892751955CDB1CBFEC8D042363023A580B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
