VALUES ('doc-14-nist-sp-800-53-p47-12', 'doc-14-nist-sp-800-53', '', 47, '(3) ACCOUNT MANAGEMENT | DISABLE ACCOUNTS Disable accounts within [Assignment: organization-defined time period] when the accounts:', 'kb-doc-14-nist-sp-800-53-p47-12', 0, 16, '14-nist-sp-800-53', 'retrieved', 'A297C780198BB435B06B6628AE1A4B874B9217C24DB5119BA448EF4FEC66BC2E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
