VALUES ('doc-14-nist-sp-800-53-p48-1', 'doc-14-nist-sp-800-53', '', 48, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 21 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p48-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'E88503385C796E92B1E2AAFEC6CA3ACF7DE3CD617F821FB0D0A5AA77430EADCD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
