INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p48-2', 'doc-14-nist-sp-800-53', '', 48, '(a) Have expired; (b) Are no longer associated with a user or individual; (c) Are in violation of organizational policy; or (d) Have been inactive for [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p48-2', 0, 30, '14-nist-sp-800-53', 'retrieved', 'C165862F20DCF4CFAC1771183AE535C7F12F72D544F8EC35410163DDA5DEA5A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
