VALUES ('doc-14-nist-sp-800-53-p48-5', 'doc-14-nist-sp-800-53', '', 48, '(4) ACCOUNT MANAGEMENT | AUTOMATED AUDIT ACTIONS Automatically audit account creation, modification, enabling, disabling, and removal actions.', 'kb-doc-14-nist-sp-800-53-p48-5', 0, 17, '14-nist-sp-800-53', 'retrieved', '6E44ECCFF7B469802C80B999B17E44AE7541C72984813B35B056E80950FB8708', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
