VALUES ('doc-14-nist-sp-800-53-p50-1', 'doc-14-nist-sp-800-53', '', 50, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 23 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p50-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0B35BF1B7607F367F6BA8771DD94B63A8BE7D6539589CD097070D0ABD56064B5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
