VALUES ('doc-14-nist-sp-800-53-p50-2', 'doc-14-nist-sp-800-53', '', 50, 'usage in their privacy impact assessment and make determinations that are in alignment with their privacy program plan.', 'kb-doc-14-nist-sp-800-53-p50-2', 0, 18, '14-nist-sp-800-53', 'retrieved', 'DD4741B1FC1E1652C7192179FA0C81249C60C364AFAC10857BAE0ED7F931EA58', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
