VALUES ('doc-14-nist-sp-800-53-p50-4', 'doc-14-nist-sp-800-53', '', 50, '(13) ACCOUNT MANAGEMENT | DISABLE ACCOUNTS FOR HIGH-RISK INDIVIDUALS Disable accounts of individuals within [Assignment: organization-defined time period] of discovery of [Assignment: organization-defined significant risks].', 'kb-doc-14-nist-sp-800-53-p50-4', 0, 25, '14-nist-sp-800-53', 'retrieved', 'A15C74AAD63C575FEF29DF327EBEE1D64B3098F97F0152F262A454E85769DF34', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
