INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p50-5', 'doc-14-nist-sp-800-53', '', 50, 'Discussion: Users who pose a significant security and/or privacy risk include individuals for whom reliable evidence indicates either the intention to use authorized access to systems to cause harm or through whom adversaries will cause harm. Such harm includes adverse impacts to organizational operations, organizational assets, individuals, other organizations, or the Nation. Close coordination among system administrators, legal staff, human resource managers, and authorizing officials is essential when disabling system accounts for high-risk individuals.', 'kb-doc-14-nist-sp-800-53-p50-5', 0, 74, '14-nist-sp-800-53', 'retrieved', '0FA7C1E813D90ADF355795BFB17077A2C912A0220038095FB79D11C8D47733B4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p50-8', 'doc-14-nist-sp-800-53', '', 50, 'AC-3 ACCESS ENFORCEMENT Control: Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control policies.', 'kb-doc-14-nist-sp-800-53-p50-8', 0, 22, '14-nist-sp-800-53', 'retrieved', '8C90CD1B4552384B22465AF969C983324597A357713D03300D6BBCB3C4345488', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
