VALUES ('doc-14-nist-sp-800-53-p53-1', 'doc-14-nist-sp-800-53', '', 53, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 26 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p53-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'E9AB7DAF9E1AD32F709E4D4D395032B39FA285DD37BA9D25BBFDD7C0B2979D08', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
