INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p55-8', 'doc-14-nist-sp-800-53', '', 55, 'Discussion: Simultaneously implementing a mandatory access control policy and a discretionary access control policy can provide additional protection against the unauthorized execution of code by users or processes acting on behalf of users. This helps prevent a single compromised user or process from compromising the entire system.', 'kb-doc-14-nist-sp-800-53-p55-8', 0, 47, '14-nist-sp-800-53', 'retrieved', '8E14E4DD08BE71901E5B272E0DAE30510CDACD91E4B586EB9B255E7BB62EA262', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
