INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p56-2', 'doc-14-nist-sp-800-53', '', 56, 'flows, and implementing trustworthy regrading mechanisms to reassign security or privacy attributes and labels.', 'kb-doc-14-nist-sp-800-53-p56-2', 0, 14, '14-nist-sp-800-53', 'retrieved', 'C0C2508C655B4C4EFAD8059F5178E3710B1E646EAFE541E1DDBE12E30C3E610D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
