INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p57-3', 'doc-14-nist-sp-800-53', '', 57, '(3) INFORMATION FLOW ENFORCEMENT | DYNAMIC INFORMATION FLOW CONTROL Enforce [Assignment: organization-defined information flow control policies].', 'kb-doc-14-nist-sp-800-53-p57-3', 0, 16, '14-nist-sp-800-53', 'retrieved', 'F95059D0BADA36734CD76ED14EE9816949DA689079BC6AD186E062597F7C7DF9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
