INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p58-12', 'doc-14-nist-sp-800-53', '', 58, 'Discussion: Documentation contains detailed information for configuring security or privacy policy filters. For example, administrators can configure security or privacy policy filters to include the list of inappropriate words that security or privacy policy mechanisms check in accordance with the definitions provided by organizations.', 'kb-doc-14-nist-sp-800-53-p58-12', 0, 44, '14-nist-sp-800-53', 'retrieved', 'EA0423E1AC319A3ACAF57C4F832C4B59947314CDFF4A67D83AC846681745AC16', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
