VALUES ('doc-14-nist-sp-800-53-p59-1', 'doc-14-nist-sp-800-53', '', 59, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 32 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p59-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '62A80490901A00451B0DA6359B52206494FAAFC998211DD1319477692E07BB54', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
