VALUES ('doc-14-nist-sp-800-53-p60-2', 'doc-14-nist-sp-800-53', '', 60, 'Uniquely identify and authenticate source and destination points by [Selection (one or more): organization; system; application; service; individual] for information transfer.', 'kb-doc-14-nist-sp-800-53-p60-2', 0, 21, '14-nist-sp-800-53', 'retrieved', 'E3F5562822042C1EADD5E4300761F45A425CDDCADE18B398495107243B61677D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
