INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p61-10', 'doc-14-nist-sp-800-53', '', 61, '(25) INFORMATION FLOW ENFORCEMENT | DATA SANITIZATION When transferring information between different security domains, sanitize data to minimize [Selection (one or more): delivery of malicious content, command and control of malicious code, malicious code augmentation, and steganography encoded data; spillage of sensitive information] in accordance with [Assignment: organization-defined policy]].', 'kb-doc-14-nist-sp-800-53-p61-10', 0, 49, '14-nist-sp-800-53', 'retrieved', '934E08BB8C868C080F1A5E58AA5F0D7ACECD8AC7A488C823D4258E326F87C769', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p61-11', 'doc-14-nist-sp-800-53', '', 61, 'Discussion: Data sanitization is the process of irreversibly removing or destroying data stored on a memory device (e.g., hard drives, flash memory/solid state drives, mobile devices, CDs, and DVDs) or in hard copy form.', 'kb-doc-14-nist-sp-800-53-p61-11', 0, 34, '14-nist-sp-800-53', 'retrieved', '2F26BC164EE96D844ED63A354CDA37D9C37E8853E75EA15D9B75ED1560ADA7E0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
