INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p61-13', 'doc-14-nist-sp-800-53', '', 61, '(26) INFORMATION FLOW ENFORCEMENT | AUDIT FILTERING ACTIONS When transferring information between different security domains, record and audit content filtering actions and results for the information being filtered.', 'kb-doc-14-nist-sp-800-53-p61-13', 0, 28, '14-nist-sp-800-53', 'retrieved', '1A81DB8CC3329141DEE56239009FCE663607AECC3E5F70D6031CA726F9CDA563', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
