INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p61-14', 'doc-14-nist-sp-800-53', '', 61, 'Discussion: Content filtering is the process of inspecting information as it traverses a cross- domain solution and determines if the information meets a predefined policy. Content filtering actions and the results of filtering actions are recorded for individual messages to ensure that the correct filter actions were applied. Content filter reports are used to assist in troubleshooting actions by, for example, determining why message content was modified and/or why it failed the filtering process. Audit events are defined in AU-2. Audit records are generated in AU-12.', 'kb-doc-14-nist-sp-800-53-p61-14', 0, 86, '14-nist-sp-800-53', 'retrieved', '7751367EF15AA5BCB978D65BBC214B1DD9C989C9DB6113AC3362C16038E66658', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p61-16', 'doc-14-nist-sp-800-53', '', 61, '(27) INFORMATION FLOW ENFORCEMENT | REDUNDANT/INDEPENDENT FILTERING MECHANISMS When transferring information between different security domains, implement content filtering solutions that provide redundant and independent filtering mechanisms for each data type.', 'kb-doc-14-nist-sp-800-53-p61-16', 0, 30, '14-nist-sp-800-53', 'retrieved', 'E62E73D661DDFF378290E46054C2CA7267C41AEF25B297390887B4DF568CEEB0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
