VALUES ('doc-14-nist-sp-800-53-p62-1', 'doc-14-nist-sp-800-53', '', 62, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 35 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p62-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '3EC4FDA72F6AC0D649373FA11B7056133C3E44E347D3A835D5C20A4BC4FC7D8D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
