VALUES ('doc-14-nist-sp-800-53-p62-2', 'doc-14-nist-sp-800-53', '', 62, 'and independent content filtering eliminates a single point of failure filtering system.', 'kb-doc-14-nist-sp-800-53-p62-2', 0, 12, '14-nist-sp-800-53', 'retrieved', '128ECA291509C674CF88885835441BB6819E0C77DA40C961B297B4BF60A1D6FC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
