INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p62-12', 'doc-14-nist-sp-800-53', '', 62, 'Discussion: The use of multiple processes to implement content filtering mechanisms reduces the likelihood of a single point of failure.', 'kb-doc-14-nist-sp-800-53-p62-12', 0, 20, '14-nist-sp-800-53', 'retrieved', '5FBB7F36DDA42FC627BB550EAE2C45FEE71CBFEB16D45CB826D4609812AF8AC6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
