INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p62-15', 'doc-14-nist-sp-800-53', '', 62, 'Discussion: Content that failed filtering checks can corrupt the system if transferred to the receiving domain.', 'kb-doc-14-nist-sp-800-53-p62-15', 0, 16, '14-nist-sp-800-53', 'retrieved', '25947436056800D75D45C067B79C19CDE5CCA11B3C8C8F457FCE425B842DADC2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
