VALUES ('doc-14-nist-sp-800-53-p63-1', 'doc-14-nist-sp-800-53', '', 63, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 36 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p63-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '8324707E893A007FD2F6A1BA6E18485D4C689FCADC7CAD35EBBF26893352BD3A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
