INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p63-3', 'doc-14-nist-sp-800-53', '', 63, 'Discussion: The processes transferring information between filter pipelines have minimum complexity and functionality to provide assurance that the processes operate correctly.', 'kb-doc-14-nist-sp-800-53-p63-3', 0, 21, '14-nist-sp-800-53', 'retrieved', 'E745CDB0643C9EB48D24D1ECDF98E22313F22E152C47D2F047BD902D681BF2BB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
