VALUES ('doc-14-nist-sp-800-53-p63-14', 'doc-14-nist-sp-800-53', '', 63, 'Related Controls: AC-2, AC-3, AC-5, AC-16, CM-5, CM-11, PL-2, PM-12, SA-8, SA-15, SA-17, SC-38.', 'kb-doc-14-nist-sp-800-53-p63-14', 0, 14, '14-nist-sp-800-53', 'retrieved', 'CABE6502A9320100463D6DF303BEDAAA064999507E942D20BAA1BCE0CB06B93A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
