INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p66-9', 'doc-14-nist-sp-800-53', '', 66, 'Discussion: A mobile device is a computing device that has a small form factor such that it can be carried by a single individual; is designed to operate without a physical connection; possesses local, non-removable or removable data storage; and includes a self-contained power source. Purging or wiping the device applies only to mobile devices for which the organization-defined number of unsuccessful logons occurs. The logon is to the mobile', 'kb-doc-14-nist-sp-800-53-p66-9', 0, 70, '14-nist-sp-800-53', 'retrieved', 'A12885D23EAC8613B76D583E9189D45BACFE2266DD1E4D4035F5DE621F3B1CFA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
