INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p67-2', 'doc-14-nist-sp-800-53', '', 67, 'device, not to any one account on the device. Successful logons to accounts on mobile devices reset the unsuccessful logon count to zero. Purging or wiping may be unnecessary if the information on the device is protected with sufficiently strong encryption mechanisms.', 'kb-doc-14-nist-sp-800-53-p67-2', 0, 42, '14-nist-sp-800-53', 'retrieved', 'C9DC3136641F9E6082EB837B2307B319EE880FD28FA985C77BB6663D47BF144E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
