INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p67-4', 'doc-14-nist-sp-800-53', '', 67, '(3) UNSUCCESSFUL LOGON ATTEMPTS | BIOMETRIC ATTEMPT LIMITING Limit the number of unsuccessful biometric logon attempts to [Assignment: organization- defined number].', 'kb-doc-14-nist-sp-800-53-p67-4', 0, 21, '14-nist-sp-800-53', 'retrieved', '1421592B9400EE7CCE1C3EA7DD0F15C53C3530952DD3905CC3690C4ECD8C25DA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
