INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p68-11', 'doc-14-nist-sp-800-53', '', 68, 'Discussion: Information about the number of unsuccessful logon attempts since the last successful logon allows the user to recognize if the number of unsuccessful logon attempts is consistent with the user’s actual logon attempts.', 'kb-doc-14-nist-sp-800-53-p68-11', 0, 34, '14-nist-sp-800-53', 'retrieved', '4D78D881319C2CF2B52DE9BB6FC498E7B002CA9A8463F0E44BC0FC1B99EBA84D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
