INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p68-13', 'doc-14-nist-sp-800-53', '', 68, '(2) PREVIOUS LOGON NOTIFICATION | SUCCESSFUL AND UNSUCCESSFUL LOGONS Notify the user, upon successful logon, of the number of [Selection: successful logons; unsuccessful logon attempts; both] during [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p68-13', 0, 31, '14-nist-sp-800-53', 'retrieved', '7E4AC1613B350192A0754AFB2DC164E9C19446FB7A01036C5D7BB976C727AEA4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
