INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p68-14', 'doc-14-nist-sp-800-53', '', 68, 'Discussion: Information about the number of successful and unsuccessful logon attempts within a specified time period allows the user to recognize if the number and type of logon attempts are consistent with the user’s actual logon attempts.', 'kb-doc-14-nist-sp-800-53-p68-14', 0, 37, '14-nist-sp-800-53', 'retrieved', 'AE5AA5CB8F66A2AF23CD2EEBB96AD307E3C103010727212746FD013BECC0A6A3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
