INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p68-16', 'doc-14-nist-sp-800-53', '', 68, '(3) PREVIOUS LOGON NOTIFICATION | NOTIFICATION OF ACCOUNT CHANGES Notify the user, upon successful logon, of changes to [Assignment: organization-defined security-related characteristics or parameters of the user’s account] during [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p68-16', 0, 33, '14-nist-sp-800-53', 'retrieved', 'F8D945BF4C1E57DEFD7B6315D90717E44769AEA0768FA0073E8480BE11C01A7A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
