INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p68-17', 'doc-14-nist-sp-800-53', '', 68, 'Discussion: Information about changes to security-related account characteristics within a specified time period allows users to recognize if changes were made without their knowledge.', 'kb-doc-14-nist-sp-800-53-p68-17', 0, 24, '14-nist-sp-800-53', 'retrieved', 'CD4A6B826B60BBA6DD37A8A94CA6B05FCC8612507AD066C51F36F28852377262', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
