INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p69-3', 'doc-14-nist-sp-800-53', '', 69, '(4) PREVIOUS LOGON NOTIFICATION | ADDITIONAL LOGON INFORMATION Notify the user, upon successful logon, of the following additional information: [Assignment: organization-defined additional information].', 'kb-doc-14-nist-sp-800-53-p69-3', 0, 23, '14-nist-sp-800-53', 'retrieved', 'E3E381678A2736401ECDF5CB60325DB369D935ED88566CC438A2917E76A9F647', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
