VALUES ('doc-14-nist-sp-800-53-p70-1', 'doc-14-nist-sp-800-53', '', 70, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 43 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p70-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'AEACAECFC9CB3617B277907E86026246876258D2B097401DAD09F9CF71332BC0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
