INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-2', 'doc-14-nist-sp-800-53', '', 70, 'Discussion: The pattern-hiding display can include static or dynamic images, such as patterns used with screen savers, photographic images, solid colors, clock, battery life indicator, or a blank screen with the caveat that controlled unclassified information is not displayed.', 'kb-doc-14-nist-sp-800-53-p70-2', 0, 39, '14-nist-sp-800-53', 'retrieved', '4624443BF81BF3729F8A1B2C007FCB40905A17C8B72903C725031A8F4E9CAB33', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
