INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-5', 'doc-14-nist-sp-800-53', '', 70, 'AC-12 SESSION TERMINATION Control: Automatically terminate a user session after [Assignment: organization-defined conditions or trigger events requiring session disconnect].', 'kb-doc-14-nist-sp-800-53-p70-5', 0, 19, '14-nist-sp-800-53', 'retrieved', 'E13B7BE108F7BC3C30F88AA35338CEAB4B47C7033520F81464B254158467A432', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-6', 'doc-14-nist-sp-800-53', '', 70, 'Discussion: Session termination addresses the termination of user-initiated logical sessions (in contrast to SC-10, which addresses the termination of network connections associated with communications sessions (i.e., network disconnect)). A logical session (for local, network, and remote access) is initiated whenever a user (or process acting on behalf of a user) accesses an organizational system. Such user sessions can be terminated without terminating network sessions. Session termination ends all processes associated with a user’s logical session except for those processes that are specifically created by the user (i.e., session owner) to continue after the session is terminated. Conditions or trigger events that require automatic termination of the session include organization-defined periods of user inactivity, targeted responses to certain types of incidents, or time-of-day restrictions on system use.', 'kb-doc-14-nist-sp-800-53-p70-6', 0, 126, '14-nist-sp-800-53', 'retrieved', 'FFD0482EF020B761B2EF433891C0C3623B70CF46B8F95C3061EAE7B2158F1F32', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-8', 'doc-14-nist-sp-800-53', '', 70, 'Control Enhancements: (1) SESSION TERMINATION | USER-INITIATED LOGOUTS Provide a logout capability for user-initiated communications sessions whenever authentication is used to gain access to [Assignment: organization-defined information resources].', 'kb-doc-14-nist-sp-800-53-p70-8', 0, 28, '14-nist-sp-800-53', 'retrieved', '2711800C6562205E5495ACC771DC45B60DE48CE908A91252C75503509731DD57', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-9', 'doc-14-nist-sp-800-53', '', 70, 'Discussion: Information resources to which users gain access via authentication include local workstations, databases, and password-protected websites or web-based services.', 'kb-doc-14-nist-sp-800-53-p70-9', 0, 20, '14-nist-sp-800-53', 'retrieved', 'E94BAE0BFBBAEE33B341C43EB924C387764467C942BADCAFA9AC398AEAD52021', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-11', 'doc-14-nist-sp-800-53', '', 70, '(2) SESSION TERMINATION | TERMINATION MESSAGE Display an explicit logout message to users indicating the termination of authenticated communications sessions.', 'kb-doc-14-nist-sp-800-53-p70-11', 0, 20, '14-nist-sp-800-53', 'retrieved', '0858599822A6B7EBDFED494755D940615347E2DCBC894B0B385987E99324D92D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-12', 'doc-14-nist-sp-800-53', '', 70, 'Discussion: Logout messages for web access can be displayed after authenticated sessions have been terminated. However, for certain types of sessions, including file transfer protocol (FTP) sessions, systems typically send logout messages as final messages prior to terminating sessions.', 'kb-doc-14-nist-sp-800-53-p70-12', 0, 39, '14-nist-sp-800-53', 'retrieved', 'BB6191B6B0C085190470ECCB78ECD8554F5B74EBB22DA1A1A3331E309DB73D0D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-14', 'doc-14-nist-sp-800-53', '', 70, '(3) SESSION TERMINATION | TIMEOUT WARNING MESSAGE Display an explicit message to users indicating that the session will end in [Assignment: organization-defined time until end of session].', 'kb-doc-14-nist-sp-800-53-p70-14', 0, 27, '14-nist-sp-800-53', 'retrieved', '26AA9AE9003D9D03DD934DF786B78F0D774001DE596E7947E627368359D91533', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
