INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p70-15', 'doc-14-nist-sp-800-53', '', 70, 'Discussion: To increase usability, notify users of pending session termination and prompt users to continue the session. The pending session termination time period is based on the parameters defined in the AC-12 base control.', 'kb-doc-14-nist-sp-800-53-p70-15', 0, 34, '14-nist-sp-800-53', 'retrieved', '55331F0360AB3DDE0273D2400EBFF28410D8BF5BD60F13F3DD572A50954E9273', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
