VALUES ('doc-14-nist-sp-800-53-p71-1', 'doc-14-nist-sp-800-53', '', 71, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 44 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p71-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '174FD63D64FF824E4936640289D792F1173DA6DB038431958FD1EF451C607253', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
