INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p71-6', 'doc-14-nist-sp-800-53', '', 71, 'AC-15 AUTOMATED MARKING [Withdrawn: Incorporated into MP-3.] AC-16 SECURITY AND PRIVACY ATTRIBUTES Control: a. Provide the means to associate [Assignment: organization-defined types of security and privacy attributes] with [Assignment: organization-defined security and privacy attribute values] for information in storage, in process, and/or in transmission; b. Ensure that the attribute associations are made and retained with the information; c. Establish the following permitted security and privacy attributes from the attributes defined in AC-16a for [Assignment: organization-defined systems]: [Assignment: organization-defined security and privacy attributes];', 'kb-doc-14-nist-sp-800-53-p71-6', 0, 82, '14-nist-sp-800-53', 'retrieved', '42CEAECEFE84B61BC1E463929BD46515816E0D0631C4997781DE66951533D77D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
