VALUES ('doc-14-nist-sp-800-53-p73-1', 'doc-14-nist-sp-800-53', '', 73, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 46 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p73-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '746BCD741C78AB458C0CD29D24F549D3744551007CD3975F75EFE5297A5FE677', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
