INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p73-2', 'doc-14-nist-sp-800-53', '', 73, 'Related Controls: AC-3, AC-4, AC-6, AC-21, AC-25, AU-2, AU-10, MP-3, PE-22, PT-2, PT-3, PT-4, SC-11, SC-16, SI-12, SI-18.', 'kb-doc-14-nist-sp-800-53-p73-2', 0, 18, '14-nist-sp-800-53', 'retrieved', '2D145895611456B8293221ADAC3FDACFCAB6E2063EFD86A4B1509C9FFD784686', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
