INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p74-9', 'doc-14-nist-sp-800-53', '', 74, '(7) SECURITY AND PRIVACY ATTRIBUTES | CONSISTENT ATTRIBUTE INTERPRETATION Provide a consistent interpretation of security and privacy attributes transmitted between distributed system components.', 'kb-doc-14-nist-sp-800-53-p74-9', 0, 23, '14-nist-sp-800-53', 'retrieved', 'B0B8E6473CE9E309163830E2E32A0F2D61ED32F4FDCA1AA4D402C2038304AFBD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
