INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p74-12', 'doc-14-nist-sp-800-53', '', 74, '(8) SECURITY AND PRIVACY ATTRIBUTES | ASSOCIATION TECHNIQUES AND TECHNOLOGIES Implement [Assignment: organization-defined techniques and technologies] in associating security and privacy attributes to information.', 'kb-doc-14-nist-sp-800-53-p74-12', 0, 24, '14-nist-sp-800-53', 'retrieved', '192BE6A7D18413C6571D906283A426BE2ED389663FC9FCB36FFE7AF8452BD48E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
