INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p74-13', 'doc-14-nist-sp-800-53', '', 74, 'Discussion: The association of security and privacy attributes to information within systems is important for conducting automated access enforcement and flow enforcement actions.', 'kb-doc-14-nist-sp-800-53-p74-13', 0, 23, '14-nist-sp-800-53', 'retrieved', '3A8C6F7BA65A75B5EF745A42BC5C885F553C17D24ADA028490CA7889AC931406', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
