INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p74-14', 'doc-14-nist-sp-800-53', '', 74, 'The association of such attributes to information (i.e., binding) can be accomplished with technologies and techniques that provide different levels of assurance. For example, systems can cryptographically bind attributes to information using digital signatures that support cryptographic keys protected by hardware devices (sometimes known as hardware roots of trust).', 'kb-doc-14-nist-sp-800-53-p74-14', 0, 49, '14-nist-sp-800-53', 'retrieved', '4360F5DC75888A5C424139B8046C21FD519B7367FA0E1129A2E7285E31B6E90A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
