INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p74-16', 'doc-14-nist-sp-800-53', '', 74, '(9) SECURITY AND PRIVACY ATTRIBUTES | ATTRIBUTE REASSIGNMENT — REGRADING MECHANISMS Change security and privacy attributes associated with information only via regrading mechanisms validated using [Assignment: organization-defined techniques or procedures].', 'kb-doc-14-nist-sp-800-53-p74-16', 0, 30, '14-nist-sp-800-53', 'retrieved', '015D04E15FBEDDC190C3464B9DAAD18456662D7284396ABD2529F66A3E02F396', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
