INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p74-17', 'doc-14-nist-sp-800-53', '', 74, 'Discussion: A regrading mechanism is a trusted process authorized to re-classify and re-label data in accordance with a defined policy exception. Validated regrading mechanisms are', 'kb-doc-14-nist-sp-800-53-p74-17', 0, 25, '14-nist-sp-800-53', 'retrieved', 'CF3E3E3F7A657B3ED045B886B03F50033BEFD2863D1A2D0E4167E3BFACED5679', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
