INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p75-2', 'doc-14-nist-sp-800-53', '', 75, 'used by organizations to provide the requisite levels of assurance for attribute reassignment activities. The validation is facilitated by ensuring that regrading mechanisms are single purpose and of limited function. Since security and privacy attribute changes can directly affect policy enforcement actions, implementing trustworthy regrading mechanisms is necessary to help ensure that such mechanisms perform in a consistent and correct mode of operation.', 'kb-doc-14-nist-sp-800-53-p75-2', 0, 63, '14-nist-sp-800-53', 'retrieved', 'E0610C3746BC9A8772E4F2AE0D212A3FD9DF0E5B8F4DE9F5F65334F25EC0DDEF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
