INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p75-4', 'doc-14-nist-sp-800-53', '', 75, '(10) SECURITY AND PRIVACY ATTRIBUTES | ATTRIBUTE CONFIGURATION BY AUTHORIZED INDIVIDUALS Provide authorized individuals the capability to define or change the type and value of security and privacy attributes available for association with subjects and objects.', 'kb-doc-14-nist-sp-800-53-p75-4', 0, 36, '14-nist-sp-800-53', 'retrieved', '14D336B362ECFF6C38DE77AD85F46650722D2C46C53ECD75BE4EAB25BD18A873', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
