INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p75-5', 'doc-14-nist-sp-800-53', '', 75, 'Discussion: The content or assigned values of security and privacy attributes can directly affect the ability of individuals to access organizational information. Thus, it is important for systems to be able to limit the ability to create or modify the type and value of attributes available for association with subjects and objects to authorized individuals only.', 'kb-doc-14-nist-sp-800-53-p75-5', 0, 56, '14-nist-sp-800-53', 'retrieved', 'BDBD9780CF7DE35910C73414FA749A3E8D85B6866BD58CF315F5D66D105613E0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
