VALUES ('doc-14-nist-sp-800-53-p75-7', 'doc-14-nist-sp-800-53', '', 75, 'References: [OMB A-130], [FIPS 140-3], [FIPS 186-4], [SP 800-162], [SP 800-178].', 'kb-doc-14-nist-sp-800-53-p75-7', 0, 11, '14-nist-sp-800-53', 'retrieved', '312EC520C2C19B4ABCEB4D2C42DAD308CA55D791A7ED604FC0F609701F5EE3CA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
