INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p75-12', 'doc-14-nist-sp-800-53', '', 75, 'Control Enhancements: (1) REMOTE ACCESS | MONITORING AND CONTROL Employ automated mechanisms to monitor and control remote access methods.', 'kb-doc-14-nist-sp-800-53-p75-12', 0, 19, '14-nist-sp-800-53', 'retrieved', 'D6E5E17F0C4699D35F716E6316F06404D07B1B52AE295072E34DD168446BC12F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
