INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p75-13', 'doc-14-nist-sp-800-53', '', 75, 'Discussion: Monitoring and control of remote access methods allows organizations to detect attacks and help ensure compliance with remote access policies by auditing the connection activities of remote users on a variety of system components, including servers,', 'kb-doc-14-nist-sp-800-53-p75-13', 0, 37, '14-nist-sp-800-53', 'retrieved', '8FB8BE9DDBE80F021C541A3BBCCD7BA1CCF14E12F49CF3C2EEF6ECB4DB01A1E8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
