VALUES ('doc-14-nist-sp-800-53-p76-4', 'doc-14-nist-sp-800-53', '', 76, '(2) REMOTE ACCESS | PROTECTION OF CONFIDENTIALITY AND INTEGRITY USING ENCRYPTION Implement cryptographic mechanisms to protect the confidentiality and integrity of remote access sessions.', 'kb-doc-14-nist-sp-800-53-p76-4', 0, 24, '14-nist-sp-800-53', 'retrieved', '34B67A2B19541F5FD5A4A7BBA25A6760661818EB8E1ED2AFA62C178FDEBA26A5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
