INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p76-5', 'doc-14-nist-sp-800-53', '', 76, 'Discussion: Virtual private networks can be used to protect the confidentiality and integrity of remote access sessions. Transport Layer Security (TLS) is an example of a cryptographic protocol that provides end-to-end communications security over networks and is used for Internet communications and online transactions.', 'kb-doc-14-nist-sp-800-53-p76-5', 0, 44, '14-nist-sp-800-53', 'retrieved', '2B7C0FA926EFF11C37D8E7187B57876ACA6EE53514FE9C85238AB4CD9A68EC36', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
