INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p76-7', 'doc-14-nist-sp-800-53', '', 76, '(3) REMOTE ACCESS | MANAGED ACCESS CONTROL POINTS Route remote accesses through authorized and managed network access control points.', 'kb-doc-14-nist-sp-800-53-p76-7', 0, 19, '14-nist-sp-800-53', 'retrieved', '4039BABB2ABA4E9E9F5DB51E16B568F70D2F9CB47D23B9667586C17BEDBA09BE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
