INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p76-8', 'doc-14-nist-sp-800-53', '', 76, 'Discussion: Organizations consider the Trusted Internet Connections (TIC) initiative [DHS TIC] requirements for external network connections since limiting the number of access control points for remote access reduces attack surfaces.', 'kb-doc-14-nist-sp-800-53-p76-8', 0, 30, '14-nist-sp-800-53', 'retrieved', '540987662DA09133AA7A3E8EF207EED62AD152897826C2645EE7D280BBA9AE86', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p76-10', 'doc-14-nist-sp-800-53', '', 76, '(4) REMOTE ACCESS | PRIVILEGED COMMANDS AND ACCESS (a) Authorize the execution of privileged commands and access to security-relevant information via remote access only in a format that provides assessable evidence and for the following needs: [Assignment: organization-defined needs]; and (b) Document the rationale for remote access in the security plan for the system.', 'kb-doc-14-nist-sp-800-53-p76-10', 0, 54, '14-nist-sp-800-53', 'retrieved', '926D40A08ECE3B4710328A187AE11F56DED1F09508E878BFEBBEA2B9A9A1C2E0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p76-11', 'doc-14-nist-sp-800-53', '', 76, 'Discussion: Remote access to systems represents a significant potential vulnerability that can be exploited by adversaries. As such, restricting the execution of privileged commands and access to security-relevant information via remote access reduces the exposure of the organization and the susceptibility to threats by adversaries to the remote access capability.', 'kb-doc-14-nist-sp-800-53-p76-11', 0, 50, '14-nist-sp-800-53', 'retrieved', '8054D5E768F39FF085296AD615EEE056ACE99E28151EE44AD3F7E9B7CCB6C41B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p76-13', 'doc-14-nist-sp-800-53', '', 76, '(5) REMOTE ACCESS | MONITORING FOR UNAUTHORIZED CONNECTIONS [Withdrawn: Incorporated into SI-4.] (6) REMOTE ACCESS | PROTECTION OF MECHANISM INFORMATION Protect information about remote access mechanisms from unauthorized use and disclosure.', 'kb-doc-14-nist-sp-800-53-p76-13', 0, 31, '14-nist-sp-800-53', 'retrieved', '209F76DA382744E2393412833C11600A953C434600225ABAE82FC626A99511BE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p76-14', 'doc-14-nist-sp-800-53', '', 76, 'Discussion: Remote access to organizational information by non-organizational entities can increase the risk of unauthorized use and disclosure about remote access mechanisms. The organization considers including remote access requirements in the information exchange agreements with other organizations, as applicable. Remote access requirements can also be included in rules of behavior (see PL-4) and access agreements (see PS-6).', 'kb-doc-14-nist-sp-800-53-p76-14', 0, 57, '14-nist-sp-800-53', 'retrieved', '52A3F245BC011B8BA7002CD7F24CD429695D3DFED85C99E9188BBAB31AD6BEC7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p76-16', 'doc-14-nist-sp-800-53', '', 76, '(7) REMOTE ACCESS | ADDITIONAL PROTECTION FOR SECURITY FUNCTION ACCESS [Withdrawn: Incorporated into AC-3(10).] (8) REMOTE ACCESS | DISABLE NONSECURE NETWORK PROTOCOLS [Withdrawn: Incorporated into CM-7.] (9) REMOTE ACCESS | DISCONNECT OR DISABLE ACCESS', 'kb-doc-14-nist-sp-800-53-p76-16', 0, 34, '14-nist-sp-800-53', 'retrieved', 'D312C8A3C4DDDEB62C63EE13F88444B149642D3DBA9E7DE462F28289911D57A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
