VALUES ('doc-14-nist-sp-800-53-p77-1', 'doc-14-nist-sp-800-53', '', 77, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 50 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p77-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'CAA9CF2EE59255CD091FA1DE0ADC25F90A849C68A2D9C3164A035A306DBEE9B3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
