INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p77-2', 'doc-14-nist-sp-800-53', '', 77, 'Provide the capability to disconnect or disable remote access to the system within [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p77-2', 0, 17, '14-nist-sp-800-53', 'retrieved', 'CF21900DB65F3147D7A06414065975F54952A589F3691F485177250F1B00FF9B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
