INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p77-3', 'doc-14-nist-sp-800-53', '', 77, 'Discussion: The speed of system disconnect or disablement varies based on the criticality of missions or business functions and the need to eliminate immediate or future remote access to systems.', 'kb-doc-14-nist-sp-800-53-p77-3', 0, 30, '14-nist-sp-800-53', 'retrieved', '612F6422B9889CCA7AD7E4E8D1A8F937378DAE48834C5F39B8122EED22F2EF27', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
