VALUES ('doc-14-nist-sp-800-53-p77-8', 'doc-14-nist-sp-800-53', '', 77, 'References: [SP 800-46], [SP 800-77], [SP 800-113], [SP 800-114], [SP 800-121], [IR 7966].', 'kb-doc-14-nist-sp-800-53-p77-8', 0, 13, '14-nist-sp-800-53', 'retrieved', 'EBB3C8CCBA302B95BBDABF30DAB974D0D7B4D11C8EC8AA778FCFBAEF46317CB3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
