INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p77-9', 'doc-14-nist-sp-800-53', '', 77, 'AC-18 WIRELESS ACCESS Control: a. Establish configuration requirements, connection requirements, and implementation guidance for each type of wireless access; and b. Authorize each type of wireless access to the system prior to allowing such connections.', 'kb-doc-14-nist-sp-800-53-p77-9', 0, 35, '14-nist-sp-800-53', 'retrieved', '5EC7734DD546F0E7F027F6AF401F78A610A049542572F5A38C13B400D359E921', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
