INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p77-10', 'doc-14-nist-sp-800-53', '', 77, 'Discussion: Wireless technologies include microwave, packet radio (ultra-high frequency or very high frequency), 802.11x, and Bluetooth. Wireless networks use authentication protocols that provide authenticator protection and mutual authentication.', 'kb-doc-14-nist-sp-800-53-p77-10', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F17D003C5B52421F73B24E932744C5D7462D7B958A1991E65BE75C763BFD04E0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
