INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p77-11', 'doc-14-nist-sp-800-53', '', 77, 'Related Controls: AC-2, AC-3, AC-17, AC-19, CA-9, CM-7, IA-2, IA-3, IA-8, PL-4, SC-40, SC-43, SI-4.', 'kb-doc-14-nist-sp-800-53-p77-11', 0, 15, '14-nist-sp-800-53', 'retrieved', 'E1BDA8D2ED5A46F23E27C05CA5964A3D046F4990E273A350A15EBB4749796673', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
