INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p77-12', 'doc-14-nist-sp-800-53', '', 77, 'Control Enhancements: (1) WIRELESS ACCESS | AUTHENTICATION AND ENCRYPTION Protect wireless access to the system using authentication of [Selection (one or more): users; devices] and encryption.', 'kb-doc-14-nist-sp-800-53-p77-12', 0, 26, '14-nist-sp-800-53', 'retrieved', '87F08DEEBA57E92B75DC3E0FCF33835BC25A4C1CB67E63D7B3BA0779BFF3742E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p77-13', 'doc-14-nist-sp-800-53', '', 77, 'Discussion: Wireless networking capabilities represent a significant potential vulnerability that can be exploited by adversaries. To protect systems with wireless access points, strong authentication of users and devices along with strong encryption can reduce susceptibility to threats by adversaries involving wireless technologies.', 'kb-doc-14-nist-sp-800-53-p77-13', 0, 42, '14-nist-sp-800-53', 'retrieved', '545E299B0D42ABD80E5E7E5C1B0FF8B4F17118AF71191E2215A81FA425D0ED12', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p77-15', 'doc-14-nist-sp-800-53', '', 77, '(2) WIRELESS ACCESS | MONITORING UNAUTHORIZED CONNECTIONS [Withdrawn: Incorporated into SI-4.] (3) WIRELESS ACCESS | DISABLE WIRELESS NETWORKING Disable, when not intended for use, wireless networking capabilities embedded within system components prior to issuance and deployment.', 'kb-doc-14-nist-sp-800-53-p77-15', 0, 36, '14-nist-sp-800-53', 'retrieved', '79BAB768CFAF1D39C39189D5E8BD5D1A853EC4794853D76585EF4DAA084ABC87', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
