VALUES ('doc-14-nist-sp-800-53-p80-1', 'doc-14-nist-sp-800-53', '', 80, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 53 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p80-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'A1C7A0858CA23F1B13CA3F927B0F76DD92FB2B7E91831F660D9BD3E333C20EFF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
