INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p80-2', 'doc-14-nist-sp-800-53', '', 80, 'Employ [Selection: full-device encryption; container-based encryption] to protect the confidentiality and integrity of information on [Assignment: organization-defined mobile devices].', 'kb-doc-14-nist-sp-800-53-p80-2', 0, 19, '14-nist-sp-800-53', 'retrieved', '1140DA24B3A9684B0D0D81F83F09E2A241599F3AA491A34FFDF29A290C98A926', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
