INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p80-3', 'doc-14-nist-sp-800-53', '', 80, 'Discussion: Container-based encryption provides a more fine-grained approach to data and information encryption on mobile devices, including encrypting selected data structures such as files, records, or fields.', 'kb-doc-14-nist-sp-800-53-p80-3', 0, 27, '14-nist-sp-800-53', 'retrieved', '2A6FDF353A8F8E0A4C79D6CB5B50F57DBA22EB925E88A9E82ED08FE591742549', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
