VALUES ('doc-14-nist-sp-800-53-p81-1', 'doc-14-nist-sp-800-53', '', 81, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 54 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p81-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D90D067EA408F8BB81161964211606DA4A8578E471AA46BC766715A600D06340', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
