INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-2', 'doc-14-nist-sp-800-53', '', 81, 'systems from external systems and the highest security category of information that can be processed, stored, or transmitted on external systems. If the terms and conditions with the owners of the external systems cannot be established, organizations may impose restrictions on organizational personnel using those external systems.', 'kb-doc-14-nist-sp-800-53-p81-2', 0, 47, '14-nist-sp-800-53', 'retrieved', '677EC887483F7FD0B24F10C97D223BB01CE2AB19C323D8A889EB9233D550A34C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
