INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-4', 'doc-14-nist-sp-800-53', '', 81, 'Control Enhancements: (1) USE OF EXTERNAL SYSTEMS | LIMITS ON AUTHORIZED USE Permit authorized individuals to use an external system to access the system or to process, store, or transmit organization-controlled information only after: (a) Verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans; or (b) Retention of approved system connection or processing agreements with the organizational entity hosting the external system.', 'kb-doc-14-nist-sp-800-53-p81-4', 0, 77, '14-nist-sp-800-53', 'retrieved', '7DF9676C3FF3CF185B43101E126C4E4828F5BF7CBAA9FBF914E424A3CE5DC222', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-5', 'doc-14-nist-sp-800-53', '', 81, 'Discussion: Limiting authorized use recognizes circumstances where individuals using external systems may need to access organizational systems. Organizations need assurance that the external systems contain the necessary controls so as not to compromise, damage, or otherwise harm organizational systems. Verification that the required controls have been implemented can be achieved by external, independent assessments, attestations, or other means, depending on the confidence level required by organizations.', 'kb-doc-14-nist-sp-800-53-p81-5', 0, 66, '14-nist-sp-800-53', 'retrieved', 'AE535E3A49161C4E4BB139654B362A2C63CB6C612F0BA0B43FF435D93F9F242D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-7', 'doc-14-nist-sp-800-53', '', 81, '(2) USE OF EXTERNAL SYSTEMS | PORTABLE STORAGE DEVICES — RESTRICTED USE Restrict the use of organization-controlled portable storage devices by authorized individuals on external systems using [Assignment: organization-defined restrictions].', 'kb-doc-14-nist-sp-800-53-p81-7', 0, 30, '14-nist-sp-800-53', 'retrieved', '89D5D98E72BBF87B1B88D1642150B54F37A0F62DE21665E3155F72E4E8263D1E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
