INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-8', 'doc-14-nist-sp-800-53', '', 81, 'Discussion: Limits on the use of organization-controlled portable storage devices in external systems include restrictions on how the devices may be used and under what conditions the devices may be used.', 'kb-doc-14-nist-sp-800-53-p81-8', 0, 31, '14-nist-sp-800-53', 'retrieved', 'A9F2A7B0187788B3D689B884519748FEE9F53691CB0E72B4B8CA45ECC24CA8E4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
