INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-10', 'doc-14-nist-sp-800-53', '', 81, '(3) USE OF EXTERNAL SYSTEMS | NON-ORGANIZATIONALLY OWNED SYSTEMS — RESTRICTED USE Restrict the use of non-organizationally owned systems or system components to process, store, or transmit organizational information using [Assignment: organization-defined restrictions].', 'kb-doc-14-nist-sp-800-53-p81-10', 0, 33, '14-nist-sp-800-53', 'retrieved', 'E46C786E4A5A505BFA5269061CDA8ACC3D9DCDBD5EE9E4144661C28CE408FD83', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
