INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-11', 'doc-14-nist-sp-800-53', '', 81, 'Discussion: Non-organizationally owned systems or system components include systems or system components owned by other organizations as well as personally owned devices.', 'kb-doc-14-nist-sp-800-53-p81-11', 0, 22, '14-nist-sp-800-53', 'retrieved', 'D593DE301C6E3A3716F94A3D0860F1388578ED211C74DC33A75CAAF44ACA6861', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-12', 'doc-14-nist-sp-800-53', '', 81, 'There are potential risks to using non-organizationally owned systems or components. In some cases, the risk is sufficiently high as to prohibit such use (see AC-20 b.). In other cases, the use of such systems or system components may be allowed but restricted in some way.', 'kb-doc-14-nist-sp-800-53-p81-12', 0, 46, '14-nist-sp-800-53', 'retrieved', '9940F91534E6DB5A7033CBEF6B64C039DB237C15FD832CD802A97D6EDC9072F1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p81-13', 'doc-14-nist-sp-800-53', '', 81, 'Restrictions include requiring the implementation of approved controls prior to authorizing the connection of non-organizationally owned systems and components; limiting access to types of information, services, or applications; using virtualization techniques to limit processing and storage activities to servers or system components provisioned by the organization; and agreeing to the terms and conditions for usage. Organizations consult with the Office of the General Counsel regarding legal issues associated with using personally owned devices, including requirements for conducting forensic analyses during investigations after an incident.', 'kb-doc-14-nist-sp-800-53-p81-13', 0, 84, '14-nist-sp-800-53', 'retrieved', 'EB122FE00C571E48E3AE1D4857248E116D28DE6741E67655FD6158F3E10034D6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
