VALUES ('doc-14-nist-sp-800-53-p82-3', 'doc-14-nist-sp-800-53', '', 82, 'Discussion: Network-accessible storage devices in external systems include online storage devices in public, hybrid, or community cloud-based systems.', 'kb-doc-14-nist-sp-800-53-p82-3', 0, 18, '14-nist-sp-800-53', 'retrieved', '868A12204224D094FD41837CE66EC2F2051ABB8F5449A6AFF085354ECE9D7A1E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
