VALUES ('doc-14-nist-sp-800-53-p82-5', 'doc-14-nist-sp-800-53', '', 82, '(5) USE OF EXTERNAL SYSTEMS | PORTABLE STORAGE DEVICES — PROHIBITED USE Prohibit the use of organization-controlled portable storage devices by authorized individuals on external systems.', 'kb-doc-14-nist-sp-800-53-p82-5', 0, 26, '14-nist-sp-800-53', 'retrieved', '8944AB7EB8834F86C67AA55CF66338D6817DEEBFDA8E56117AB8C9D30BBD8764', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
