INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p82-6', 'doc-14-nist-sp-800-53', '', 82, 'Discussion: Limits on the use of organization-controlled portable storage devices in external systems include a complete prohibition of the use of such devices. Prohibiting such use is enforced using technical methods and/or nontechnical (i.e., process-based) methods.', 'kb-doc-14-nist-sp-800-53-p82-6', 0, 36, '14-nist-sp-800-53', 'retrieved', '6214FADB264A69431C41E0255E1B68465BD28D79D25338C06778EB50AAFCAE34', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
