VALUES ('doc-14-nist-sp-800-53-p82-13', 'doc-14-nist-sp-800-53', '', 82, 'Control Enhancements: (1) INFORMATION SHARING | AUTOMATED DECISION SUPPORT Employ [Assignment: organization-defined automated mechanisms] to enforce information-sharing decisions by authorized users based on access authorizations of sharing partners and access restrictions on information to be shared.', 'kb-doc-14-nist-sp-800-53-p82-13', 0, 36, '14-nist-sp-800-53', 'retrieved', 'AF245D82643127AE77AF968E80A9CAFE5F7F20BD69ECD98423DD50E5284F1A11', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
