INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p83-4', 'doc-14-nist-sp-800-53', '', 83, 'AC-22 PUBLICLY ACCESSIBLE CONTENT Control: a. Designate individuals authorized to make information publicly accessible; b. Train authorized individuals to ensure that publicly accessible information does not contain nonpublic information; c. Review the proposed content of information prior to posting onto the publicly accessible system to ensure that nonpublic information is not included; and d. Review the content on the publicly accessible system for nonpublic information [Assignment: organization-defined frequency] and remove such information, if discovered.', 'kb-doc-14-nist-sp-800-53-p83-4', 0, 74, '14-nist-sp-800-53', 'retrieved', 'F9D921D8F8D459EF1F69CECB5EB166CFECFABBED4F34BD1FA8CE7A7AB0C40B04', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
