VALUES ('doc-14-nist-sp-800-53-p84-1', 'doc-14-nist-sp-800-53', '', 84, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 57 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p84-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '127328B0F8CB763A8FBE686B6ED67E79332CFD95CE1281E6C7B31530EE5BE2AC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
