VALUES ('doc-14-nist-sp-800-53-p84-2', 'doc-14-nist-sp-800-53', '', 84, 'and is available as open-source information residing on external sites, such as social networking or social media websites.', 'kb-doc-14-nist-sp-800-53-p84-2', 0, 18, '14-nist-sp-800-53', 'retrieved', '2C7CAC4235CA6FF707CC7E3643CA764F6912B43A6B4ACDB96932CB479DBDAEFE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
