INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p84-3', 'doc-14-nist-sp-800-53', '', 84, '[EO 13587] requires the establishment of an insider threat program for deterring, detecting, and mitigating insider threats, including the safeguarding of sensitive information from exploitation, compromise, or other unauthorized disclosure. Data mining protection requires organizations to identify appropriate techniques to prevent and detect unnecessary or unauthorized data mining.', 'kb-doc-14-nist-sp-800-53-p84-3', 0, 48, '14-nist-sp-800-53', 'retrieved', 'E13F42B3FDC21F91BD727AFF20641E83894E037DE382B3A0E666E3D6950B976A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p84-4', 'doc-14-nist-sp-800-53', '', 84, 'Data mining can be used by an insider to collect organizational information for the purpose of exfiltration.', 'kb-doc-14-nist-sp-800-53-p84-4', 0, 17, '14-nist-sp-800-53', 'retrieved', 'C1653BAFF7604A57703B3D47F60C178565F5764C31FB5445F5A1DC06B10DABF2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
