VALUES ('doc-14-nist-sp-800-53-p86-1', 'doc-14-nist-sp-800-53', '', 86, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 59 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p86-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'E975A4BBD21757970A88AD03B94AC34070D4F10702F978DB4F37FF938057F72B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
