INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p87-6', 'doc-14-nist-sp-800-53', '', 87, 'Control Enhancements: (1) LITERACY TRAINING AND AWARENESS | PRACTICAL EXERCISES Provide practical exercises in literacy training that simulate events and incidents.', 'kb-doc-14-nist-sp-800-53-p87-6', 0, 21, '14-nist-sp-800-53', 'retrieved', '58570ED177D9519D040287741C3BA8BCA235D2E91F8E388465EBF6341732E5B8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
