INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p87-7', 'doc-14-nist-sp-800-53', '', 87, 'Discussion: Practical exercises include no-notice social engineering attempts to collect information, gain unauthorized access, or simulate the adverse impact of opening malicious email attachments or invoking, via spear phishing attacks, malicious web links.', 'kb-doc-14-nist-sp-800-53-p87-7', 0, 33, '14-nist-sp-800-53', 'retrieved', 'E539B6373C36837686DB8FEDAB4D1EFE0C21CBC3D000CE3FE4F59458D24EF383', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
