INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p87-9', 'doc-14-nist-sp-800-53', '', 87, '(2) LITERACY TRAINING AND AWARENESS | INSIDER THREAT Provide literacy training on recognizing and reporting potential indicators of insider threat.', 'kb-doc-14-nist-sp-800-53-p87-9', 0, 20, '14-nist-sp-800-53', 'retrieved', 'C37AB5233869F68D0890D2565FD0F74CA8FC1FABD3E2529862095D4C1B7B2FB4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
