INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p88-8', 'doc-14-nist-sp-800-53', '', 88, '(4) LITERACY TRAINING AND AWARENESS | SUSPICIOUS COMMUNICATIONS AND ANOMALOUS SYSTEM BEHAVIOR Provide literacy training on recognizing suspicious communications and anomalous behavior in organizational systems using [Assignment: organization-defined indicators of malicious code].', 'kb-doc-14-nist-sp-800-53-p88-8', 0, 32, '14-nist-sp-800-53', 'retrieved', '6BA570432B47E14D8D326E01ED2D46141A078B47F08517D2441F55AC3B8D6A96', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
