VALUES ('doc-14-nist-sp-800-53-p88-12', 'doc-14-nist-sp-800-53', '', 88, '(5) LITERACY TRAINING AND AWARENESS | ADVANCED PERSISTENT THREAT Provide literacy training on the advanced persistent threat.', 'kb-doc-14-nist-sp-800-53-p88-12', 0, 17, '14-nist-sp-800-53', 'retrieved', '1479580DA7457D990538625C9F993D5E315F3436A47EAE3BEA98783A9714FFAE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
