INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p88-13', 'doc-14-nist-sp-800-53', '', 88, 'Discussion: An effective way to detect advanced persistent threats (APT) and to preclude successful attacks is to provide specific literacy training for individuals. Threat literacy training includes educating individuals on the various ways that APTs can infiltrate the organization (e.g., through websites, emails, advertisement pop-ups, articles, and social', 'kb-doc-14-nist-sp-800-53-p88-13', 0, 48, '14-nist-sp-800-53', 'retrieved', 'D5ADA18E63971FA62DEEE97DCBEB427A033C8B4C9FD96550E9B614DF22124F4D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
