VALUES ('doc-14-nist-sp-800-53-p89-1', 'doc-14-nist-sp-800-53', '', 89, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 62 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p89-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '090A1EAE1A4A20948F76B295BEE60725E4254AA18AAAF0618E634FEAC6674817', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
