INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p89-4', 'doc-14-nist-sp-800-53', '', 89, '(6) LITERACY TRAINING AND AWARENESS | CYBER THREAT ENVIRONMENT (a) Provide literacy training on the cyber threat environment; and (b) Reflect current cyber threat information in system operations.', 'kb-doc-14-nist-sp-800-53-p89-4', 0, 28, '14-nist-sp-800-53', 'retrieved', '3961F3CF0122A959ECE1C2E078DADADF95513F374A7329FB4AD319E04668B892', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
