INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p89-5', 'doc-14-nist-sp-800-53', '', 89, 'Discussion: Since threats continue to change over time, threat literacy training by the organization is dynamic. Moreover, threat literacy training is not performed in isolation from the system operations that support organizational mission and business functions.', 'kb-doc-14-nist-sp-800-53-p89-5', 0, 36, '14-nist-sp-800-53', 'retrieved', '4D44768A17465C592010ED50A0A847C29DB55107B22C57446425982DA395B268', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
