VALUES ('doc-14-nist-sp-800-53-p90-2', 'doc-14-nist-sp-800-53', '', 90, 'training on a regular basis helps to ensure that the content remains relevant and effective.', 'kb-doc-14-nist-sp-800-53-p90-2', 0, 15, '14-nist-sp-800-53', 'retrieved', '0341D20EBDB7CBB0B16CADEB9699CDE2B174C83642C72487ED350EB3647DB519', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
