INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p90-3', 'doc-14-nist-sp-800-53', '', 90, 'Events that may precipitate an update to role-based training content include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.', 'kb-doc-14-nist-sp-800-53-p90-3', 0, 37, '14-nist-sp-800-53', 'retrieved', '32A3A7E55F41CA956D4BC583F20D23E7E721A54ED5AC74E14C5C2E72DACC9E8E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
