VALUES ('doc-14-nist-sp-800-53-p90-4', 'doc-14-nist-sp-800-53', '', 90, 'Related Controls: AC-3, AC-17, AC-22, AT-2, AT-4, CP-3, IR-2, IR-4, IR-7, IR-9, PL-4, PM-13, PM-23, PS-7, PS-9, SA-3, SA-8, SA-11, SA-16, SR-5, SR-6, SR-11.', 'kb-doc-14-nist-sp-800-53-p90-4', 0, 24, '14-nist-sp-800-53', 'retrieved', '6A3046DA7196B1F9251AD823CEEA202BB419B9FE59D9D4084A7542882B6AFC19', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
