INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p90-6', 'doc-14-nist-sp-800-53', '', 90, 'Discussion: Environmental controls include fire suppression and detection devices or systems, sprinkler systems, handheld fire extinguishers, fixed fire hoses, smoke detectors, temperature or humidity, heating, ventilation, air conditioning, and power within the facility.', 'kb-doc-14-nist-sp-800-53-p90-6', 0, 33, '14-nist-sp-800-53', 'retrieved', '68AE98129C280E9946E4C172965B140D278FF1F1B353C5637F52D2D06DF49F89', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
