VALUES ('doc-14-nist-sp-800-53-p90-8', 'doc-14-nist-sp-800-53', '', 90, '(2) ROLE-BASED TRAINING | PHYSICAL SECURITY CONTROLS Provide [Assignment: organization-defined personnel or roles] with initial and [Assignment: organization-defined frequency] training in the employment and operation of physical security controls.', 'kb-doc-14-nist-sp-800-53-p90-8', 0, 29, '14-nist-sp-800-53', 'retrieved', 'FD7E765CA45867EE11C213A2D92F4F8F7674C9C3232B2D9FE1A3555C5D5E4146', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
