INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p90-9', 'doc-14-nist-sp-800-53', '', 90, 'Discussion: Physical security controls include physical access control devices, physical intrusion and detection alarms, operating procedures for facility security guards, and monitoring or surveillance equipment.', 'kb-doc-14-nist-sp-800-53-p90-9', 0, 25, '14-nist-sp-800-53', 'retrieved', '4ED734A2C71FAEF71B1C845DAD7D73945567F7D4B7712B9576C6873B43B5CDA6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
