INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p90-11', 'doc-14-nist-sp-800-53', '', 90, '(3) ROLE-BASED TRAINING | PRACTICAL EXERCISES Provide practical exercises in security and privacy training that reinforce training objectives.', 'kb-doc-14-nist-sp-800-53-p90-11', 0, 18, '14-nist-sp-800-53', 'retrieved', '27D0E026E7077165AFDC95AC74CC572AA7B6DF59A263B836ED93BCEFB546396E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
