INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p90-16', 'doc-14-nist-sp-800-53', '', 90, 'Discussion: Personally identifiable information processing and transparency controls include the organization’s authority to process personally identifiable information and personally identifiable information processing purposes. Role-based training for federal agencies addresses the types of information that may constitute personally identifiable information and the risks, considerations, and obligations associated with its processing. Such training also considers the authority to process personally identifiable information documented in privacy policies and notices, system of records notices, computer matching agreements and', 'kb-doc-14-nist-sp-800-53-p90-16', 0, 74, '14-nist-sp-800-53', 'retrieved', 'FAE75FCF2D9451573DB66D2D9D6BADFB23869955F9A83D4704D9AE370D7A5714', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
