INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p91-11', 'doc-14-nist-sp-800-53', '', 91, 'Discussion: Training feedback includes awareness training results and role-based training results.', 'kb-doc-14-nist-sp-800-53-p91-11', 0, 11, '14-nist-sp-800-53', 'retrieved', 'BB402FFEB689B209DE5BA016B59C4728458293E93FCED2908D07261A3522329F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
