INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p91-12', 'doc-14-nist-sp-800-53', '', 91, 'Training results, especially failures of personnel in critical roles, can be indicative of a potentially serious problem. Therefore, it is important that senior managers are made aware of such situations so that they can take appropriate response actions. Training feedback supports the evaluation and update of organizational training described in AT-2b and AT-3b.', 'kb-doc-14-nist-sp-800-53-p91-12', 0, 53, '14-nist-sp-800-53', 'retrieved', '760D2542CE6722263CA9349F6AE67F5FCF64FE133CB91E52F103FAB6B60214F6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
