VALUES ('doc-14-nist-sp-800-53-p92-1', 'doc-14-nist-sp-800-53', '', 92, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 65 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p92-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'CB5B6E4241596BDB8301179188A7E5C3EDB61DAE7267AFF371B3FC89C26F5081', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
