VALUES ('doc-14-nist-sp-800-53-p94-1', 'doc-14-nist-sp-800-53', '', 94, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 67 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p94-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'FA46C4DF3B93DFC0E896C2F1E859E098ADB262B3955D37F239E4E83106718137', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
