INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p94-2', 'doc-14-nist-sp-800-53', '', 94, 'Control Enhancements: (1) EVENT LOGGING | COMPILATION OF AUDIT RECORDS FROM MULTIPLE SOURCES [Withdrawn: Incorporated into AU-12.] (2) EVENT LOGGING | SELECTION OF AUDIT EVENTS BY COMPONENT [Withdrawn: Incorporated into AU-12.] (3) EVENT LOGGING | REVIEWS AND UPDATES [Withdrawn: Incorporated into AU-2.] (4) EVENT LOGGING | PRIVILEGED FUNCTIONS [Withdrawn: Incorporated into AC-6(9).] References: [OMB A-130], [SP 800-92].', 'kb-doc-14-nist-sp-800-53-p94-2', 0, 57, '14-nist-sp-800-53', 'retrieved', 'B10C863E235E825074A1E0F6322E568AE73FCD1196F1E557719A76B82B024391', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
