VALUES ('doc-14-nist-sp-800-53-p95-1', 'doc-14-nist-sp-800-53', '', 95, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 68 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p95-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F4F2FD884ACEE07534715D0F67F6324AD6C51730A3391735F7C11244026EBCBF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
