INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p95-2', 'doc-14-nist-sp-800-53', '', 95, '(2) CONTENT OF AUDIT RECORDS | CENTRALIZED MANAGEMENT OF PLANNED AUDIT RECORD CONTENT [Withdrawn: Incorporated into PL-9.] (3) CONTENT OF AUDIT RECORDS | LIMIT PERSONALLY IDENTIFIABLE INFORMATION ELEMENTS Limit personally identifiable information contained in audit records to the following elements identified in the privacy risk assessment: [Assignment: organization-defined elements].', 'kb-doc-14-nist-sp-800-53-p95-2', 0, 49, '14-nist-sp-800-53', 'retrieved', 'D7CFC3158176F3C8D30E0A8C30E09881710187BBA43BF4F8A7E52F0C119037AA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
