INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p95-3', 'doc-14-nist-sp-800-53', '', 95, 'Discussion: Limiting personally identifiable information in audit records when such information is not needed for operational purposes helps reduce the level of privacy risk created by a system.', 'kb-doc-14-nist-sp-800-53-p95-3', 0, 28, '14-nist-sp-800-53', 'retrieved', '898598B450D05697959C8E4684F424B67BDAB66F15F6B0DF0F2197EA0C55A0C8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
