VALUES ('doc-14-nist-sp-800-53-p97-1', 'doc-14-nist-sp-800-53', '', 97, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 70 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p97-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '81FDC578C3814E4D99DB34BE87490B8BB566E1656632991128E69F988AEC966C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
