INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p97-2', 'doc-14-nist-sp-800-53', '', 97, 'supporting the core organizational mission and business functions. In those instances, partial system shutdowns or operating in a degraded mode with reduced capability may be viable alternatives.', 'kb-doc-14-nist-sp-800-53-p97-2', 0, 27, '14-nist-sp-800-53', 'retrieved', 'E38DE8D4E83CF8D730A3094C25206ACF3F2CEB18E655CF55DB0139765AD4CA2F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
