INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p97-12', 'doc-14-nist-sp-800-53', '', 97, 'Discussion: Organizational processes that benefit from integrated audit record review, analysis, and reporting include incident response, continuous monitoring, contingency planning, investigation and response to suspicious activities, and Inspector General audits.', 'kb-doc-14-nist-sp-800-53-p97-12', 0, 30, '14-nist-sp-800-53', 'retrieved', '23E58300A5FA3C43B8A936BB00B87A002080292E35EF3DF98D3185A9D3B4FA22', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
