INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p98-3', 'doc-14-nist-sp-800-53', '', 98, '(2) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | AUTOMATED SECURITY ALERTS [Withdrawn: Incorporated into SI-4.] (3) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | CORRELATE AUDIT RECORD REPOSITORIES Analyze and correlate audit records across different repositories to gain organization-wide situational awareness.', 'kb-doc-14-nist-sp-800-53-p98-3', 0, 40, '14-nist-sp-800-53', 'retrieved', 'F1F8A5D5ECBD7AC7614853CA21A721B325FD2C923A035D4FD48E9BF46E17D1C2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
