INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p98-4', 'doc-14-nist-sp-800-53', '', 98, 'Discussion: Organization-wide situational awareness includes awareness across all three levels of risk management (i.e., organizational level, mission/business process level, and information system level) and supports cross-organization awareness.', 'kb-doc-14-nist-sp-800-53-p98-4', 0, 27, '14-nist-sp-800-53', 'retrieved', '26FADE2E70904EA600A8C968A7FA3098D8DD67350C7C000855C7631F42589D17', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
