INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p98-6', 'doc-14-nist-sp-800-53', '', 98, '(4) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | CENTRAL REVIEW AND ANALYSIS Provide and implement the capability to centrally review and analyze audit records from multiple components within the system.', 'kb-doc-14-nist-sp-800-53-p98-6', 0, 30, '14-nist-sp-800-53', 'retrieved', '8A504B4AF51B62784B3C002A2CA9B872A177B89EDDDB723C7D5F984047EAB97C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
