INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p98-7', 'doc-14-nist-sp-800-53', '', 98, 'Discussion: Automated mechanisms for centralized reviews and analyses include Security Information and Event Management products.', 'kb-doc-14-nist-sp-800-53-p98-7', 0, 15, '14-nist-sp-800-53', 'retrieved', '87EF6D0EF8AFB9B55965AA8D804C0D53BDB354E7B7CF1DECDCB6886FD5A53B72', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
