VALUES ('doc-14-nist-sp-800-53-p99-1', 'doc-14-nist-sp-800-53', '', 99, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 72 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p99-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '2F55EA1F81A9354E467F59435DB1546507F67D7603D7AAC9C08D5083CCBF7D55', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
