INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p99-12', 'doc-14-nist-sp-800-53', '', 99, 'AU-7 AUDIT RECORD REDUCTION AND REPORT GENERATION Control: Provide and implement an audit record reduction and report generation capability that: a. Supports on-demand audit record review, analysis, and reporting requirements and after- the-fact investigations of incidents; and b. Does not alter the original content or time ordering of audit records.', 'kb-doc-14-nist-sp-800-53-p99-12', 0, 50, '14-nist-sp-800-53', 'retrieved', 'CE9ED349549084FA366BB48B60590C32D9EF22E68BB4F809ADB195E9C073D41E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
