INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p99-13', 'doc-14-nist-sp-800-53', '', 99, 'Discussion: Audit record reduction is a process that manipulates collected audit log information and organizes it into a summary format that is more meaningful to analysts. Audit record', 'kb-doc-14-nist-sp-800-53-p99-13', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F2E4A9A316A677A2E4A04A0C53320DD689D5B3F905FA39E0434D9DBD1AC8DEFE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
