VALUES ('doc-14-nist-sp-800-53-p100-1', 'doc-14-nist-sp-800-53', '', 100, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 73 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p100-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '2D719D106214C04D1B6CE83E3F8E87C640C60A539C566ECF20D6919707948C15', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
