INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p100-4', 'doc-14-nist-sp-800-53', '', 100, 'Control Enhancements: (1) AUDIT RECORD REDUCTION AND REPORT GENERATION | AUTOMATIC PROCESSING Provide and implement the capability to process, sort, and search audit records for events of interest based on the following content: [Assignment: organization-defined fields within audit records].', 'kb-doc-14-nist-sp-800-53-p100-4', 0, 39, '14-nist-sp-800-53', 'retrieved', 'BE35B0330DBE11E3FE729864883F50DB395F8C011C1BA8DCC1BD7F2E19ABC37B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p100-5', 'doc-14-nist-sp-800-53', '', 100, 'Discussion: Events of interest can be identified by the content of audit records, including system resources involved, information objects accessed, identities of individuals, event types, event locations, event dates and times, Internet Protocol addresses involved, or event success or failure. Organizations may define event criteria to any degree of granularity required, such as locations selectable by a general networking location or by specific system component.', 'kb-doc-14-nist-sp-800-53-p100-5', 0, 65, '14-nist-sp-800-53', 'retrieved', 'DF79F498E9BCD40A171D49644E7FD3DB35EB42E11FD9B391F60D24E9D4C15FEE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
