VALUES ('doc-14-nist-sp-800-53-p100-7', 'doc-14-nist-sp-800-53', '', 100, '(2) AUDIT RECORD REDUCTION AND REPORT GENERATION | AUTOMATIC SORT AND SEARCH [Withdrawn: Incorporated into AU-7(1).] References: None.', 'kb-doc-14-nist-sp-800-53-p100-7', 0, 18, '14-nist-sp-800-53', 'retrieved', '73CFDBDA1A422BAA008F01BC3673ABAEBA132A9B67F476DB1D6E1C374EEA7095', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
