VALUES ('doc-14-nist-sp-800-53-p100-11', 'doc-14-nist-sp-800-53', '', 100, 'Control Enhancements: (1) TIME STAMPS | SYNCHRONIZATION WITH AUTHORITATIVE TIME SOURCE [Withdrawn: Moved to SC-45(1).] (2) TIME STAMPS | SECONDARY AUTHORITATIVE TIME SOURCE', 'kb-doc-14-nist-sp-800-53-p100-11', 0, 23, '14-nist-sp-800-53', 'retrieved', 'D0F2C134F305C306D1E71C2AFEE190A4A5E1D53DF8903789FB669F3044547CC7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
