VALUES ('doc-14-nist-sp-800-53-p101-1', 'doc-14-nist-sp-800-53', '', 101, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 74 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p101-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '4A1C7E400576EBA9C247E83CD4C7E12123D02C5AC30980F95B6BF66AF2D895C5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
