VALUES ('doc-14-nist-sp-800-53-p104-1', 'doc-14-nist-sp-800-53', '', 104, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 77 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p104-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '3A810EB750D11E62CAEFC549B71CB3B6923651AF8CBB72B65B1C3153EE50C366', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
