INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p104-4', 'doc-14-nist-sp-800-53', '', 104, '(4) NON-REPUDIATION | VALIDATE BINDING OF INFORMATION REVIEWER IDENTITY (a) Validate the binding of the information reviewer identity to the information at the transfer or release points prior to release or transfer between [Assignment: organization-defined security domains]; and (b) Perform [Assignment: organization-defined actions] in the event of a validation error.', 'kb-doc-14-nist-sp-800-53-p104-4', 0, 50, '14-nist-sp-800-53', 'retrieved', '838103F71F4C18CC7AD3BCA15EAB82EDAFBD750F5456A7C089BAA575560929C0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
