INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p104-5', 'doc-14-nist-sp-800-53', '', 104, 'Discussion: Validating the binding of the information reviewer identity to the information at transfer or release points prevents the unauthorized modification of information between review and the transfer or release. The validation of bindings can be achieved by using cryptographic checksums. Organizations determine if validations are in response to user requests or generated automatically.', 'kb-doc-14-nist-sp-800-53-p104-5', 0, 54, '14-nist-sp-800-53', 'retrieved', '0337CC1E139482031F883BB1ACC0458DD88A87D6E1F2F8D613C5A1191657657F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
