INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p104-8', 'doc-14-nist-sp-800-53', '', 104, 'AU-11 AUDIT RECORD RETENTION Control: Retain audit records for [Assignment: organization-defined time period consistent with records retention policy] to provide support for after-the-fact investigations of incidents and to meet regulatory and organizational information retention requirements.', 'kb-doc-14-nist-sp-800-53-p104-8', 0, 35, '14-nist-sp-800-53', 'retrieved', '93F9A914F70B83A1A371286D8617A5C4052E25BAAE7A0A909E31B30A4246A4A9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p104-9', 'doc-14-nist-sp-800-53', '', 104, 'Discussion: Organizations retain audit records until it is determined that the records are no longer needed for administrative, legal, audit, or other operational purposes. This includes the retention and availability of audit records relative to Freedom of Information Act (FOIA) requests, subpoenas, and law enforcement actions. Organizations develop standard categories of audit records relative to such types of actions and standard response processes for each type of action.', 'kb-doc-14-nist-sp-800-53-p104-9', 0, 68, '14-nist-sp-800-53', 'retrieved', 'A38836AECCAC4F82BE20FEA46514C74B0DA4ECA7124642777102BDD5980EEC5F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p104-10', 'doc-14-nist-sp-800-53', '', 104, 'The National Archives and Records Administration (NARA) General Records Schedules provide federal policy on records retention.', 'kb-doc-14-nist-sp-800-53-p104-10', 0, 16, '14-nist-sp-800-53', 'retrieved', 'AE182189D4289FD64585777016A1D029E1819A6A02B5D254884CF20D985C3CB1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
