INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p104-12', 'doc-14-nist-sp-800-53', '', 104, 'Control Enhancements: (1) AUDIT RECORD RETENTION | LONG-TERM RETRIEVAL CAPABILITY Employ [Assignment: organization-defined measures] to ensure that long-term audit records generated by the system can be retrieved.', 'kb-doc-14-nist-sp-800-53-p104-12', 0, 27, '14-nist-sp-800-53', 'retrieved', '40822193F95F3B73B79CA00454DF0E968C4BE404B0FE89D919D61C6BC9F39FC6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p104-13', 'doc-14-nist-sp-800-53', '', 104, 'Discussion: Organizations need to access and read audit records requiring long-term storage (on the order of years). Measures employed to help facilitate the retrieval of audit records include converting records to newer formats, retaining equipment capable of reading the records, and retaining the necessary documentation to help personnel understand how to interpret the records.', 'kb-doc-14-nist-sp-800-53-p104-13', 0, 54, '14-nist-sp-800-53', 'retrieved', 'BEDC2EEB6B5FAF1B0EB1F60128B6B645AB02096602D0330ABADF18762C3613E4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-1', 'doc-14-nist-sp-800-53', '', 105, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 78 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p105-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F9A3FC007687A21AF6BE304F26B57E54083EA9372BF9A51561FC6B5A171E5F36', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-2', 'doc-14-nist-sp-800-53', '', 105, 'a. Provide audit record generation capability for the event types the system is capable of auditing as defined in AU-2a on [Assignment: organization-defined system components]; b. Allow [Assignment: organization-defined personnel or roles] to select the event types that are to be logged by specific components of the system; and c. Generate audit records for the event types defined in AU-2c that include the audit record content defined in AU-3.', 'kb-doc-14-nist-sp-800-53-p105-2', 0, 69, '14-nist-sp-800-53', 'retrieved', 'A340903B866E9F7442D3AE4AF92A04113D926D6AB6752C87D8C7399CA1C962C3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-3', 'doc-14-nist-sp-800-53', '', 105, 'Discussion: Audit records can be generated from many different system components. The event types specified in AU-2d are the event types for which audit logs are to be generated and are a subset of all event types for which the system can generate audit records.', 'kb-doc-14-nist-sp-800-53-p105-3', 0, 45, '14-nist-sp-800-53', 'retrieved', 'C0A9E08BF8CB852BA514A9E9BEB686E95CB7067A20D847ED1DC56CCC41CF7F1C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
