INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-4', 'doc-14-nist-sp-800-53', '', 105, 'Related Controls: AC-6, AC-17, AU-2, AU-3, AU-4, AU-5, AU-6, AU-7, AU-14, CM-5, MA-4, MP-4, PM-12, SA-8, SC-18, SI-3, SI-4, SI-7, SI-10.', 'kb-doc-14-nist-sp-800-53-p105-4', 0, 21, '14-nist-sp-800-53', 'retrieved', '1CC1E3A088B8D88CC1739E366AF4B9DB015B6B5F35E3E52F5D1276D92289FBA8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
