INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-5', 'doc-14-nist-sp-800-53', '', 105, 'Control Enhancements: (1) AUDIT RECORD GENERATION | SYSTEM-WIDE AND TIME-CORRELATED AUDIT TRAIL Compile audit records from [Assignment: organization-defined system components] into a system-wide (logical or physical) audit trail that is time-correlated to within [Assignment: organization-defined level of tolerance for the relationship between time stamps of individual records in the audit trail].', 'kb-doc-14-nist-sp-800-53-p105-5', 0, 51, '14-nist-sp-800-53', 'retrieved', 'C849575F12A24CFEC99919831A33B01AAE70A591B3276C6BC00B076F98746103', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-6', 'doc-14-nist-sp-800-53', '', 105, 'Discussion: Audit trails are time-correlated if the time stamps in the individual audit records can be reliably related to the time stamps in other audit records to achieve a time ordering of the records within organizational tolerances.', 'kb-doc-14-nist-sp-800-53-p105-6', 0, 37, '14-nist-sp-800-53', 'retrieved', '4BFEB5BE7C84CC8D0E3D61FD3CFA76F733FA42958F789978EE4638F09DB20928', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-8', 'doc-14-nist-sp-800-53', '', 105, '(2) AUDIT RECORD GENERATION | STANDARDIZED FORMATS Produce a system-wide (logical or physical) audit trail composed of audit records in a standardized format.', 'kb-doc-14-nist-sp-800-53-p105-8', 0, 23, '14-nist-sp-800-53', 'retrieved', 'F4371F93F43EE5A5E2C91998D05D8D08F09BE0F02FF26C3B8337E2624908DFBA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-9', 'doc-14-nist-sp-800-53', '', 105, 'Discussion: Audit records that follow common standards promote interoperability and information exchange between devices and systems. Promoting interoperability and information exchange facilitates the production of event information that can be readily analyzed and correlated. If logging mechanisms do not conform to standardized formats, systems may convert individual audit records into standardized formats when compiling system-wide audit trails.', 'kb-doc-14-nist-sp-800-53-p105-9', 0, 57, '14-nist-sp-800-53', 'retrieved', 'DB96A13E92710BBD7B460BEADC22ED3932D324113A1E1E9CF03F61A2F9AB4C2D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-11', 'doc-14-nist-sp-800-53', '', 105, '(3) AUDIT RECORD GENERATION | CHANGES BY AUTHORIZED INDIVIDUALS Provide and implement the capability for [Assignment: organization-defined individuals or roles] to change the logging to be performed on [Assignment: organization-defined system components] based on [Assignment: organization-defined selectable event criteria] within [Assignment: organization-defined time thresholds].', 'kb-doc-14-nist-sp-800-53-p105-11', 0, 44, '14-nist-sp-800-53', 'retrieved', '13A20F30AAA0613BBA5978453073145042176C82F7A1967B5B70258B422F7D7E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-12', 'doc-14-nist-sp-800-53', '', 105, 'Discussion: Permitting authorized individuals to make changes to system logging enables organizations to extend or limit logging as necessary to meet organizational requirements.', 'kb-doc-14-nist-sp-800-53-p105-12', 0, 23, '14-nist-sp-800-53', 'retrieved', 'CDBBB4C1C686ECAC982B9447FB22D99476C4886FEB85D3FE13DD421C49A26A76', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p105-13', 'doc-14-nist-sp-800-53', '', 105, 'Logging that is limited to conserve system resources may be extended (either temporarily or permanently) to address certain threat situations. In addition, logging may be limited to a specific set of event types to facilitate audit reduction, analysis, and reporting. Organizations can establish time thresholds in which logging actions are changed (e.g., near real-time, within minutes, or within hours).', 'kb-doc-14-nist-sp-800-53-p105-13', 0, 59, '14-nist-sp-800-53', 'retrieved', '2A2920F6A46C5F04061EF9DACA37DE521CC8C33A1302D428ECF15EF169F8E386', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
