VALUES ('doc-14-nist-sp-800-53-p106-1', 'doc-14-nist-sp-800-53', '', 106, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 79 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p106-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '98AD9D53627C4334A066011AC6125A209B744C676375B5C93A72414A50C4A935', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
