INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p106-2', 'doc-14-nist-sp-800-53', '', 106, '(4) AUDIT RECORD GENERATION | QUERY PARAMETER AUDITS OF PERSONALLY IDENTIFIABLE INFORMATION Provide and implement the capability for auditing the parameters of user query events for data sets containing personally identifiable information.', 'kb-doc-14-nist-sp-800-53-p106-2', 0, 32, '14-nist-sp-800-53', 'retrieved', '14DE9F847F90A110EE8B8A1A148F18BC8D880FAEDA4BDE3E76D252136A06C44C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p106-3', 'doc-14-nist-sp-800-53', '', 106, 'Discussion: Query parameters are explicit criteria that an individual or automated system submits to a system to retrieve data. Auditing of query parameters for datasets that contain personally identifiable information augments the capability of an organization to track and understand the access, usage, or sharing of personally identifiable information by authorized personnel.', 'kb-doc-14-nist-sp-800-53-p106-3', 0, 52, '14-nist-sp-800-53', 'retrieved', '79CA831B2F94E6246E38C482C9EB7DE5D4B8E54C3B380B71096C0AC85E74B399', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p106-6', 'doc-14-nist-sp-800-53', '', 106, 'AU-13 MONITORING FOR INFORMATION DISCLOSURE Control: a. Monitor [Assignment: organization-defined open-source information and/or information sites] [Assignment: organization-defined frequency] for evidence of unauthorized disclosure of organizational information; and b. If an information disclosure is discovered: 1. Notify [Assignment: organization-defined personnel or roles]; and 2. Take the following additional actions: [Assignment: organization-defined additional actions].', 'kb-doc-14-nist-sp-800-53-p106-6', 0, 52, '14-nist-sp-800-53', 'retrieved', 'A80119CCA8F4FFAEEBFD5D0B0C246E36FC3BE02D16CF0994BD86EF8200A9CC3C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p106-7', 'doc-14-nist-sp-800-53', '', 106, 'Discussion: Unauthorized disclosure of information is a form of data leakage. Open-source information includes social networking sites and code-sharing platforms and repositories.', 'kb-doc-14-nist-sp-800-53-p106-7', 0, 22, '14-nist-sp-800-53', 'retrieved', '2E948CD9EF8B3C5599A4D0DEC49E35964FEF27696D000508059E010B54622892', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
