VALUES ('doc-14-nist-sp-800-53-p106-8', 'doc-14-nist-sp-800-53', '', 106, 'Examples of organizational information include personally identifiable information retained by the organization or proprietary information generated by the organization.', 'kb-doc-14-nist-sp-800-53-p106-8', 0, 19, '14-nist-sp-800-53', 'retrieved', 'FDF93E49774960F04377B78B3B70F96AFEE6B068C6712F93B47380BF069170B1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
