INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p106-11', 'doc-14-nist-sp-800-53', '', 106, 'Discussion: Automated mechanisms include commercial services that provide notifications and alerts to organizations and automated scripts to monitor new posts on websites.', 'kb-doc-14-nist-sp-800-53-p106-11', 0, 22, '14-nist-sp-800-53', 'retrieved', '87A2747E5C382082613292F7955764D47B63522773177D7FD8795E6A8E717B22', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
