VALUES ('doc-14-nist-sp-800-53-p107-1', 'doc-14-nist-sp-800-53', '', 107, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 80 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p107-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '5ED6E2B4422CA45F0348CE51058AB7F8FD73637E76EEE8090FA0F02716EDB058', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
