INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-1', 'doc-14-nist-sp-800-53', '', 108, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 81 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p108-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '5A7408E48D285D4CE6E4D9D5E3397B2B5392A4B0E5B5B00912A44CF2CFFF1587', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-4', 'doc-14-nist-sp-800-53', '', 108, 'AU-15 ALTERNATE AUDIT LOGGING CAPABILITY [Withdrawn: Moved to AU-5(5).] AU-16 CROSS-ORGANIZATIONAL AUDIT LOGGING Control: Employ [Assignment: organization-defined methods] for coordinating [Assignment: organization-defined audit information] among external organizations when audit information is transmitted across organizational boundaries.', 'kb-doc-14-nist-sp-800-53-p108-4', 0, 35, '14-nist-sp-800-53', 'retrieved', 'DC13F8ADB36BEF71517E0AB50883F503CB528180AB3A323C523EF95EE0ABC8A1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-5', 'doc-14-nist-sp-800-53', '', 108, 'Discussion: When organizations use systems or services of external organizations, the audit logging capability necessitates a coordinated, cross-organization approach. For example, maintaining the identity of individuals who request specific services across organizational boundaries may often be difficult, and doing so may prove to have significant performance and privacy ramifications. Therefore, it is often the case that cross-organizational audit logging simply captures the identity of individuals who issue requests at the initial system, and subsequent systems record that the requests originated from authorized individuals. Organizations consider including processes for coordinating audit information requirements and protection of audit information in information exchange agreements.', 'kb-doc-14-nist-sp-800-53-p108-5', 0, 101, '14-nist-sp-800-53', 'retrieved', 'BBA03D8E99AC881F0A15D3A4CEBE1BC6DA3B56DF38E7C223B8F775351CAEABE3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-7', 'doc-14-nist-sp-800-53', '', 108, 'Control Enhancements: (1) CROSS-ORGANIZATIONAL AUDIT LOGGING | IDENTITY PRESERVATION Preserve the identity of individuals in cross-organizational audit trails.', 'kb-doc-14-nist-sp-800-53-p108-7', 0, 18, '14-nist-sp-800-53', 'retrieved', '8A5E966D8E4FFB837CA6314367E246D8F5C19C3FDB7F789C857D6780E3110C30', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-8', 'doc-14-nist-sp-800-53', '', 108, 'Discussion: Identity preservation is applied when there is a need to be able to trace actions that are performed across organizational boundaries to a specific individual.', 'kb-doc-14-nist-sp-800-53-p108-8', 0, 26, '14-nist-sp-800-53', 'retrieved', '75CD4D83F4F4D9CEC8BF905E06FDB9DA94BEE9B9CFCB02AA17B2B826A45FFC13', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-10', 'doc-14-nist-sp-800-53', '', 108, '(2) CROSS-ORGANIZATIONAL AUDIT LOGGING | SHARING OF AUDIT INFORMATION Provide cross-organizational audit information to [Assignment: organization-defined organizations] based on [Assignment: organization-defined cross-organizational sharing agreements].', 'kb-doc-14-nist-sp-800-53-p108-10', 0, 24, '14-nist-sp-800-53', 'retrieved', 'B4C520AA14351691A11918EB9A96EB8D86C874566C0D6B479D21CF0A946A41C8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-11', 'doc-14-nist-sp-800-53', '', 108, 'Discussion: Due to the distributed nature of the audit information, cross-organization sharing of audit information may be essential for effective analysis of the auditing being performed. For example, the audit records of one organization may not provide sufficient information to determine the appropriate or inappropriate use of organizational information resources by individuals in other organizations. In some instances, only individuals’ home organizations have the appropriate knowledge to make such determinations, thus requiring the sharing of audit information among organizations.', 'kb-doc-14-nist-sp-800-53-p108-11', 0, 79, '14-nist-sp-800-53', 'retrieved', 'DF7352EC7B236E4CA89E662094306FFF139F4415DCEA0C338D7EC7AD7F8AD0BA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-13', 'doc-14-nist-sp-800-53', '', 108, '(3) CROSS-ORGANIZATIONAL AUDITING | DISASSOCIABILITY Implement [Assignment: organization-defined measures] to disassociate individuals from audit information transmitted across organizational boundaries.', 'kb-doc-14-nist-sp-800-53-p108-13', 0, 19, '14-nist-sp-800-53', 'retrieved', '5E7DEB406A79288E75486F7ACF6ED7627FC022FDC798A940C4327EA7024C8AA2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
