INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-14', 'doc-14-nist-sp-800-53', '', 108, 'Discussion: Preserving identities in audit trails could have privacy ramifications, such as enabling the tracking and profiling of individuals, but may not be operationally necessary.', 'kb-doc-14-nist-sp-800-53-p108-14', 0, 25, '14-nist-sp-800-53', 'retrieved', '846665D5B75B65053E035C36CCBF0F8AF41D5E18143976EA9D31670B5591825B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
