INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p108-15', 'doc-14-nist-sp-800-53', '', 108, 'These risks could be further amplified when transmitting information across organizational boundaries. Implementing privacy-enhancing cryptographic techniques can disassociate individuals from audit information and reduce privacy risk while maintaining accountability.', 'kb-doc-14-nist-sp-800-53-p108-15', 0, 29, '14-nist-sp-800-53', 'retrieved', '1F58385EB21C7A8CB4F3C5B286CA19DA63D2F882920FBEE086761D2C9CDAAC36', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
