VALUES ('doc-14-nist-sp-800-53-p109-1', 'doc-14-nist-sp-800-53', '', 109, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 82 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p109-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '3C564F68D45B37274C34F7EC7E06582A5BA217370759C8E3B77B8963E54D71BD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
