VALUES ('doc-14-nist-sp-800-53-p110-1', 'doc-14-nist-sp-800-53', '', 110, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 83 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p110-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0FEA3594A2D8A1D726A34CD881073BEAD4F11E794DC2DC345F68AB39576A25B6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
