VALUES ('doc-14-nist-sp-800-53-p111-1', 'doc-14-nist-sp-800-53', '', 111, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 84 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p111-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F31F026B6CE26C45E018FAE0F957815D3BDA5A1ABFFB802743E64E7DA42A3137', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
