INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p111-2', 'doc-14-nist-sp-800-53', '', 111, 'References: [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-53A], [SP 800-100], [SP 800-137], [SP 800-137A], [IR 8062].', 'kb-doc-14-nist-sp-800-53-p111-2', 0, 21, '14-nist-sp-800-53', 'retrieved', '0BF4F6524D7423D85E44CFA15849EEB9CE958F38F5C1F91C1F0D5AB0118351C7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
