INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p112-5', 'doc-14-nist-sp-800-53', '', 112, 'Control Enhancements: (1) CONTROL ASSESSMENTS | INDEPENDENT ASSESSORS Employ independent assessors or assessment teams to conduct control assessments.', 'kb-doc-14-nist-sp-800-53-p112-5', 0, 18, '14-nist-sp-800-53', 'retrieved', '32C9DBB5229F2A6F4679C59844C8366D38EDADED23E6E413CB60B255554CFAFC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p112-6', 'doc-14-nist-sp-800-53', '', 112, 'Discussion: Independent assessors or assessment teams are individuals or groups who conduct impartial assessments of systems. Impartiality means that assessors are free from any perceived or actual conflicts of interest regarding the development, operation, sustainment, or management of the systems under assessment or the determination of control effectiveness. To achieve impartiality, assessors do not create a mutual or conflicting interest with the organizations where the assessments are being conducted, assess their own work, act as management or employees of the organizations they are serving, or place themselves in positions of advocacy for the organizations acquiring their services.', 'kb-doc-14-nist-sp-800-53-p112-6', 0, 97, '14-nist-sp-800-53', 'retrieved', '0DAA4873AC50A8CDE95B91027024C5D26FFEF3B1EBB382AF3E413A5FF93BC078', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
