VALUES ('doc-14-nist-sp-800-53-p113-1', 'doc-14-nist-sp-800-53', '', 113, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 86 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p113-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '4B6FF9D61C6681E432220F16678D543825882178EF52D8F188C1E8F3F27C6A35', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
