INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p113-12', 'doc-14-nist-sp-800-53', '', 113, 'CA-3 INFORMATION EXCHANGE Control: a. Approve and manage the exchange of information between the system and other systems using [Selection (one or more): interconnection security agreements; information exchange security agreements; memoranda of understanding or agreement; service level agreements;', 'kb-doc-14-nist-sp-800-53-p113-12', 0, 38, '14-nist-sp-800-53', 'retrieved', 'CF857BBCD2A29D06F4B0B259E5B0D84C8A4456802587C848FE8F6459899DDC62', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
