VALUES ('doc-14-nist-sp-800-53-p114-1', 'doc-14-nist-sp-800-53', '', 114, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 87 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p114-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0E9A47C43183F837AA6531633D3C32A3212BEC8BBFA0EDDB90C4CDCAFA4B0F5D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
