VALUES ('doc-14-nist-sp-800-53-p115-2', 'doc-14-nist-sp-800-53', '', 115, '[Withdrawn: Moved to SC-7(5).] (6) INFORMATION EXCHANGE | TRANSFER AUTHORIZATIONS Verify that individuals or systems transferring data between interconnecting systems have the requisite authorizations (i.e., write permissions or privileges) prior to accepting such data.', 'kb-doc-14-nist-sp-800-53-p115-2', 0, 34, '14-nist-sp-800-53', 'retrieved', 'FB8E48069630A40B5AC3B0EA7068D1F0F58437C92F02B5AC460250BBCFA0BEFB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
