INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p115-3', 'doc-14-nist-sp-800-53', '', 115, 'Discussion: To prevent unauthorized individuals and systems from making information transfers to protected systems, the protected system verifies— via independent means— whether the individual or system attempting to transfer information is authorized to do so.', 'kb-doc-14-nist-sp-800-53-p115-3', 0, 35, '14-nist-sp-800-53', 'retrieved', '330A2B5FEA0947031FC9D4BBB69CFC2E81EBE003605940692FBA2A4374F565F8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
