INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p115-4', 'doc-14-nist-sp-800-53', '', 115, 'Verification of the authorization to transfer information also applies to control plane traffic (e.g., routing and DNS) and services (e.g., authenticated SMTP relays).', 'kb-doc-14-nist-sp-800-53-p115-4', 0, 23, '14-nist-sp-800-53', 'retrieved', '571F765CAC3660C75589ED0E1BEA3394195F347CD9BD6DF105530049B7D57A06', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
