VALUES ('doc-14-nist-sp-800-53-p116-1', 'doc-14-nist-sp-800-53', '', 116, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 89 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p116-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0885A4543B35CDEE3DAD5F44364E09B61CE02AA2963BEB15E1871EB0FD4E0184', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
