VALUES ('doc-14-nist-sp-800-53-p118-1', 'doc-14-nist-sp-800-53', '', 118, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 91 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p118-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '5A485A2DF83EBF8E97331773F03A7025BC5373518516DE3FBFCF22446771FA85', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
