INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p118-6', 'doc-14-nist-sp-800-53', '', 118, 'Control Enhancements: (1) CONTINUOUS MONITORING | INDEPENDENT ASSESSMENT Employ independent assessors or assessment teams to monitor the controls in the system on an ongoing basis.', 'kb-doc-14-nist-sp-800-53-p118-6', 0, 25, '14-nist-sp-800-53', 'retrieved', '8C3F5230F81DC745D41A2E7CAD5710DFB3A921C76007612036F4B64532A0D3E6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p118-7', 'doc-14-nist-sp-800-53', '', 118, 'Discussion: Organizations maximize the value of control assessments by requiring that assessments be conducted by assessors with appropriate levels of independence. The level of required independence is based on organizational continuous monitoring strategies.', 'kb-doc-14-nist-sp-800-53-p118-7', 0, 33, '14-nist-sp-800-53', 'retrieved', '0F3EF482585687E264B39BB86285FF45685DA8DE018E92F8744D6BF9EDD7E6EC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p118-8', 'doc-14-nist-sp-800-53', '', 118, 'Assessor independence provides a degree of impartiality to the monitoring process. To achieve such impartiality, assessors do not create a mutual or conflicting interest with the organizations where the assessments are being conducted, assess their own work, act as management or employees of the organizations they are serving, or place themselves in advocacy positions for the organizations acquiring their services.', 'kb-doc-14-nist-sp-800-53-p118-8', 0, 60, '14-nist-sp-800-53', 'retrieved', '7ADBBCBBC2748F274230696FA4B9DD47D5C3179C1E7EF0E40CB34888FAF07055', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p118-10', 'doc-14-nist-sp-800-53', '', 118, '(2) CONTINUOUS MONITORING | TYPES OF ASSESSMENTS [Withdrawn: Incorporated into CA-2.] (3) CONTINUOUS MONITORING | TREND ANALYSES Employ trend analyses to determine if control implementations, the frequency of continuous monitoring activities, and the types of activities used in the continuous monitoring process need to be modified based on empirical data.', 'kb-doc-14-nist-sp-800-53-p118-10', 0, 50, '14-nist-sp-800-53', 'retrieved', 'DF1134F7726841FD9394C534C7CEFCA16A1990DE4433E8D66E1C1F820BB3DB50', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
