INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-1', 'doc-14-nist-sp-800-53', '', 119, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 92 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p119-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '8AEDA8335B39FCADC8A4BB9B9C71D0EACCFB1714CD1B54902329BC117FE02C71', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-2', 'doc-14-nist-sp-800-53', '', 119, 'Discussion: Trend analyses include examining recent threat information that addresses the types of threat events that have occurred in the organization or the Federal Government, success rates of certain types of attacks, emerging vulnerabilities in technologies, evolving social engineering techniques, the effectiveness of configuration settings, results from multiple control assessments, and findings from Inspectors General or auditors.', 'kb-doc-14-nist-sp-800-53-p119-2', 0, 57, '14-nist-sp-800-53', 'retrieved', 'E90005E09AB6864BD08C2D87EBBAB572CC8671ACE76E632D24C3F10023895E30', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-4', 'doc-14-nist-sp-800-53', '', 119, '(4) CONTINUOUS MONITORING | RISK MONITORING Ensure risk monitoring is an integral part of the continuous monitoring strategy that includes the following: (a) Effectiveness monitoring; (b) Compliance monitoring; and (c) Change monitoring.', 'kb-doc-14-nist-sp-800-53-p119-4', 0, 32, '14-nist-sp-800-53', 'retrieved', '621E2573E77AC70292179082CC6B033A24FB73B48386415D48C0E4C8E5D0CF23', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-5', 'doc-14-nist-sp-800-53', '', 119, 'Discussion: Risk monitoring is informed by the established organizational risk tolerance.', 'kb-doc-14-nist-sp-800-53-p119-5', 0, 11, '14-nist-sp-800-53', 'retrieved', 'A3E55AB0E1EF3C304818125539C628043C85FA98B13497D8AB58DF1579FC6115', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-6', 'doc-14-nist-sp-800-53', '', 119, 'Effectiveness monitoring determines the ongoing effectiveness of the implemented risk response measures. Compliance monitoring verifies that required risk response measures are implemented. It also verifies that security and privacy requirements are satisfied. Change monitoring identifies changes to organizational systems and environments of operation that may affect security and privacy risk.', 'kb-doc-14-nist-sp-800-53-p119-6', 0, 50, '14-nist-sp-800-53', 'retrieved', '788A17599DF1BD19A2BF650C80A1CA04F130C8323A648A2CAF23CE8BD7ABA208', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-8', 'doc-14-nist-sp-800-53', '', 119, '(5) CONTINUOUS MONITORING | CONSISTENCY ANALYSIS Employ the following actions to validate that policies are established and implemented controls are operating in a consistent manner: [Assignment: organization-defined actions].', 'kb-doc-14-nist-sp-800-53-p119-8', 0, 28, '14-nist-sp-800-53', 'retrieved', '08801169182C6491CABE3C70327DC17BFEAF1317F28FA4EED967E7C4778B8C1A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-9', 'doc-14-nist-sp-800-53', '', 119, 'Discussion: Security and privacy controls are often added incrementally to a system. As a result, policies for selecting and implementing controls may be inconsistent, and the controls could fail to work together in a consistent or coordinated manner. At a minimum, the lack of consistency and coordination could mean that there are unacceptable security and privacy gaps in the system. At worst, it could mean that some of the controls implemented in one location or by one component are actually impeding the functionality of other controls (e.g., encrypting internal network traffic can impede monitoring). In other situations, failing to consistently monitor all implemented network protocols (e.g., a dual stack of IPv4 and IPv6) may create unintended vulnerabilities in the system that could be exploited by adversaries.', 'kb-doc-14-nist-sp-800-53-p119-9', 0, 126, '14-nist-sp-800-53', 'retrieved', '62F9C711D84B83A21FFD1D1A024347FBA38BD42238D79ED5605F8799DB303024', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-10', 'doc-14-nist-sp-800-53', '', 119, 'It is important to validate— through testing, monitoring, and analysis— that the implemented controls are operating in a consistent, coordinated, non-interfering manner.', 'kb-doc-14-nist-sp-800-53-p119-10', 0, 22, '14-nist-sp-800-53', 'retrieved', 'CDEC1900286EF59354918611B067E44FA5FF79E014BBB4A87A2149F9ACFEC1AE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-12', 'doc-14-nist-sp-800-53', '', 119, '(6) CONTINUOUS MONITORING | AUTOMATION SUPPORT FOR MONITORING Ensure the accuracy, currency, and availability of monitoring results for the system using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p119-12', 0, 25, '14-nist-sp-800-53', 'retrieved', '150492E50DF63DF50AD8BBADD736473B834200917F79F8B5DF1E348B2F1B6C83', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p119-13', 'doc-14-nist-sp-800-53', '', 119, 'Discussion: Using automated tools for monitoring helps to maintain the accuracy, currency, and availability of monitoring information which in turns helps to increase the level of ongoing awareness of the system security and privacy posture in support of organizational risk management decisions.', 'kb-doc-14-nist-sp-800-53-p119-13', 0, 42, '14-nist-sp-800-53', 'retrieved', '6052C93ECDCDC108C9F91A234FBF9AC7D85C91B69BC45F821F1ACCFCFE4E0012', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
