VALUES ('doc-14-nist-sp-800-53-p120-1', 'doc-14-nist-sp-800-53', '', 120, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 93 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p120-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'FEDED9DB485FD604575959454BD9B0175BDC09E6BDD552E8786EBE88BF5F1403', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
