INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p120-2', 'doc-14-nist-sp-800-53', '', 120, 'CA-8 PENETRATION TESTING Control: Conduct penetration testing [Assignment: organization-defined frequency] on [Assignment: organization-defined systems or system components].', 'kb-doc-14-nist-sp-800-53-p120-2', 0, 17, '14-nist-sp-800-53', 'retrieved', '6CFEC6EE074FA2F792FF0154F716038CA04F9671EEB573291E60610BC93E7DDA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
