INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p122-2', 'doc-14-nist-sp-800-53', '', 122, '(1) INTERNAL SYSTEM CONNECTIONS | COMPLIANCE CHECKS Perform security and privacy compliance checks on constituent system components prior to the establishment of the internal connection.', 'kb-doc-14-nist-sp-800-53-p122-2', 0, 25, '14-nist-sp-800-53', 'retrieved', '6334E2F19986F0980CCCCBE81A5AC8052BD2020094B9DB42B0472DFC8103934E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
