INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p122-3', 'doc-14-nist-sp-800-53', '', 122, 'Discussion: Compliance checks include verification of the relevant baseline configuration.', 'kb-doc-14-nist-sp-800-53-p122-3', 0, 10, '14-nist-sp-800-53', 'retrieved', '535D76B712A68054B8F35E63D53574451F08B038105E0764DAFEB39FDDEFC7D8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
