VALUES ('doc-14-nist-sp-800-53-p123-1', 'doc-14-nist-sp-800-53', '', 123, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 96 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p123-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '5D17A4A1B3187A6906891E44298B977B70E508193DFC86E897ACA34D735ABF2B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
