VALUES ('doc-14-nist-sp-800-53-p124-1', 'doc-14-nist-sp-800-53', '', 124, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 97 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p124-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '50D8B4AE020263D02972C59C8F559890E20768DC2F2915B386A2212E847B8122', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
