INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p124-2', 'doc-14-nist-sp-800-53', '', 124, 'CM-2 BASELINE CONFIGURATION Control: a. Develop, document, and maintain under configuration control, a current baseline configuration of the system; and b. Review and update the baseline configuration of the system: 1. [Assignment: organization-defined frequency]; 2. When required due to [Assignment: organization-defined circumstances]; and 3. When system components are installed or upgraded.', 'kb-doc-14-nist-sp-800-53-p124-2', 0, 51, '14-nist-sp-800-53', 'retrieved', 'B72F6E1D5AB7A7D84A6019FDC0016D3112A3F04E079EB3FFC8BA16D199B13368', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
