INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p124-9', 'doc-14-nist-sp-800-53', '', 124, 'Discussion: Retaining previous versions of baseline configurations to support rollback include hardware, software, firmware, configuration files, configuration records, and associated documentation.', 'kb-doc-14-nist-sp-800-53-p124-9', 0, 21, '14-nist-sp-800-53', 'retrieved', 'F786044D1C33C50B9B44F6A4101FD139062F939F7B97324C47E25B65B15EBA35', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
