VALUES ('doc-14-nist-sp-800-53-p126-1', 'doc-14-nist-sp-800-53', '', 126, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 99 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p126-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'DA5DDD5A14EA077BBD2B97DCCF7A271349F6378920E840F7BB538506DC9A7436', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
