INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p126-5', 'doc-14-nist-sp-800-53', '', 126, 'Control Enhancements: (1) CONFIGURATION CHANGE CONTROL | AUTOMATED DOCUMENTATION, NOTIFICATION, AND PROHIBITION OF CHANGES Use [Assignment: organization-defined automated mechanisms] to: (a) Document proposed changes to the system; (b) Notify [Assignment: organization-defined approval authorities] of proposed changes to the system and request change approval; (c) Highlight proposed changes to the system that have not been approved or disapproved within [Assignment: organization-defined time period]; (d) Prohibit changes to the system until designated approvals are received; (e) Document all changes to the system; and (f) Notify [Assignment: organization-defined personnel] when approved changes to the system are completed.', 'kb-doc-14-nist-sp-800-53-p126-5', 0, 94, '14-nist-sp-800-53', 'retrieved', '40D8A8B217E435EF15D25EF9468B5F7CB97AF4A37D9295F7D76C41ED43505AF4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p126-8', 'doc-14-nist-sp-800-53', '', 126, '(2) CONFIGURATION CHANGE CONTROL | TESTING, VALIDATION, AND DOCUMENTATION OF CHANGES Test, validate, and document changes to the system before finalizing the implementation of the changes.', 'kb-doc-14-nist-sp-800-53-p126-8', 0, 26, '14-nist-sp-800-53', 'retrieved', 'A5C0F7D1C60BD6E165CD63BF2BDFCCA19FDE74A99174AC810FE2E2DC68D4BBE4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p126-9', 'doc-14-nist-sp-800-53', '', 126, 'Discussion: Changes to systems include modifications to hardware, software, or firmware components and configuration settings defined in CM-6. Organizations ensure that testing does not interfere with system operations that support organizational mission and business functions. Individuals or groups conducting tests understand security and privacy policies and procedures, system security and privacy policies and procedures, and the health, safety, and environmental risks associated with specific facilities or processes. Operational systems', 'kb-doc-14-nist-sp-800-53-p126-9', 0, 69, '14-nist-sp-800-53', 'retrieved', '7CC5BCB8F021551D3605ABA4000276B8CA42B009EF32119EC301365BC61023C5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
