VALUES ('doc-14-nist-sp-800-53-p127-1', 'doc-14-nist-sp-800-53', '', 127, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 100 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p127-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '5A0E5DEECC315A198B30A77A19722473DDC74C6F5D81BCF000FF04961D5088B9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
