INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p127-2', 'doc-14-nist-sp-800-53', '', 127, 'may need to be taken offline, or replicated to the extent feasible, before testing can be conducted. If systems must be taken offline for testing, the tests are scheduled to occur during planned system outages whenever possible. If the testing cannot be conducted on operational systems, organizations employ compensating controls.', 'kb-doc-14-nist-sp-800-53-p127-2', 0, 50, '14-nist-sp-800-53', 'retrieved', 'B51ACCBA5AC586162E5D909F1E3410F414D60B5D8A8CFE11ACB0E951410A3F6B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
