INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p127-4', 'doc-14-nist-sp-800-53', '', 127, '(3) CONFIGURATION CHANGE CONTROL | AUTOMATED CHANGE IMPLEMENTATION Implement changes to the current system baseline and deploy the updated baseline across the installed base using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p127-4', 0, 29, '14-nist-sp-800-53', 'retrieved', '7EB322A8C7527783F8B12EF9E2F09BA0DADB98A735399304F788478126D02E61', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p127-5', 'doc-14-nist-sp-800-53', '', 127, 'Discussion: Automated tools can improve the accuracy, consistency, and availability of configuration baseline information. Automation can also provide data aggregation and data correlation capabilities, alerting mechanisms, and dashboards to support risk-based decision-making within the organization.', 'kb-doc-14-nist-sp-800-53-p127-5', 0, 35, '14-nist-sp-800-53', 'retrieved', '225F8F0FFDC0B80D41DCC80C02422287973E6C265234F0A4ADD1DE734D9FD86E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p127-7', 'doc-14-nist-sp-800-53', '', 127, '(4) CONFIGURATION CHANGE CONTROL | SECURITY AND PRIVACY REPRESENTATIVES Require [Assignment: organization-defined security and privacy representatives] to be members of the [Assignment: organization-defined configuration change control element].', 'kb-doc-14-nist-sp-800-53-p127-7', 0, 27, '14-nist-sp-800-53', 'retrieved', '4160B1ED11625C8A0F9E76FDFB20C8E9AB1D0B1286E07F5615D0E43521B2B2F7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p127-8', 'doc-14-nist-sp-800-53', '', 127, 'Discussion: Information security and privacy representatives include system security officers, senior agency information security officers, senior agency officials for privacy, or system privacy officers. Representation by personnel with information security and privacy expertise is important because changes to system configurations can have unintended side effects, some of which may be security- or privacy-relevant. Detecting such changes early in the process can help avoid unintended, negative consequences that could ultimately affect the security and privacy posture of systems. The configuration change control element referred to in the second organization-defined parameter reflects the change control elements defined by organizations in CM-3g.', 'kb-doc-14-nist-sp-800-53-p127-8', 0, 99, '14-nist-sp-800-53', 'retrieved', 'D23C1C2720A523B59D27AC0C41E14178E386067E5220B644BF6368970DF05695', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p127-10', 'doc-14-nist-sp-800-53', '', 127, '(5) CONFIGURATION CHANGE CONTROL | AUTOMATED SECURITY RESPONSE Implement the following security responses automatically if baseline configurations are changed in an unauthorized manner: [Assignment: organization-defined security responses].', 'kb-doc-14-nist-sp-800-53-p127-10', 0, 27, '14-nist-sp-800-53', 'retrieved', 'A0F7C2E83C8C96F7FCFF7DB78DD858CC166AC0A9A1FAD0A75C05D5CD9BAC0B36', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p127-11', 'doc-14-nist-sp-800-53', '', 127, 'Discussion: Automated security responses include halting selected system functions, halting system processing, and issuing alerts or notifications to organizational personnel when there is an unauthorized modification of a configuration item.', 'kb-doc-14-nist-sp-800-53-p127-11', 0, 30, '14-nist-sp-800-53', 'retrieved', 'FB65A5B051A8BFF674CB7D4BBAF2D363F3C7F4D6C0E5480B722F2B511BE0A8D4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p127-13', 'doc-14-nist-sp-800-53', '', 127, '(6) CONFIGURATION CHANGE CONTROL | CRYPTOGRAPHY MANAGEMENT Ensure that cryptographic mechanisms used to provide the following controls are under configuration management: [Assignment: organization-defined controls].', 'kb-doc-14-nist-sp-800-53-p127-13', 0, 24, '14-nist-sp-800-53', 'retrieved', '51F5BF1396ADC2688FDCF3DD0D1EC2A8E8099350247326D20B424FA11DBA6C00', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
