INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p128-2', 'doc-14-nist-sp-800-53', '', 128, 'Review changes to the system [Assignment: organization-defined frequency] or when [Assignment: organization-defined circumstances] to determine whether unauthorized changes have occurred.', 'kb-doc-14-nist-sp-800-53-p128-2', 0, 20, '14-nist-sp-800-53', 'retrieved', '67097ADCB66A90EA163EBB1929F653A551F218DEFBB1DAEB67D124F95715F315', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
