INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p128-3', 'doc-14-nist-sp-800-53', '', 128, 'Discussion: Indications that warrant a review of changes to the system and the specific circumstances justifying such reviews may be obtained from activities carried out by organizations during the configuration change process or continuous monitoring process.', 'kb-doc-14-nist-sp-800-53-p128-3', 0, 36, '14-nist-sp-800-53', 'retrieved', '2699033E0BB6ABAAA623968E1238C8414705F9B7EA458A66A82A76DEF1B5FC1B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
