INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p128-5', 'doc-14-nist-sp-800-53', '', 128, '(8) CONFIGURATION CHANGE CONTROL | PREVENT OR RESTRICT CONFIGURATION CHANGES Prevent or restrict changes to the configuration of the system under the following circumstances: [Assignment: organization-defined circumstances].', 'kb-doc-14-nist-sp-800-53-p128-5', 0, 27, '14-nist-sp-800-53', 'retrieved', 'A14E60FBD1B2DF95A14C65B74AFD4B81A50C539379432EA387C0C5423AE0F258', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
