INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p128-6', 'doc-14-nist-sp-800-53', '', 128, 'Discussion: System configuration changes can adversely affect critical system security and privacy functionality. Change restrictions can be enforced through automated mechanisms.', 'kb-doc-14-nist-sp-800-53-p128-6', 0, 21, '14-nist-sp-800-53', 'retrieved', '4C84CF01C8EF67F172F0CAA20521089C22B03F1A6806F227C7F53F90DC020E27', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
