INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p128-9', 'doc-14-nist-sp-800-53', '', 128, 'CM-4 IMPACT ANALYSES Control: Analyze changes to the system to determine potential security and privacy impacts prior to change implementation.', 'kb-doc-14-nist-sp-800-53-p128-9', 0, 20, '14-nist-sp-800-53', 'retrieved', '9827113AAB171023368C167A098FA6E1C2BDC57A625770B459D93E587A1D7F40', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p128-10', 'doc-14-nist-sp-800-53', '', 128, 'Discussion: Organizational personnel with security or privacy responsibilities conduct impact analyses. Individuals conducting impact analyses possess the necessary skills and technical expertise to analyze the changes to systems as well as the security or privacy ramifications.', 'kb-doc-14-nist-sp-800-53-p128-10', 0, 36, '14-nist-sp-800-53', 'retrieved', '39E80E0F6B9DDF8E3DA42AC6DD4E57DE1405E16C51D52B9B3928497591408DE4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p128-11', 'doc-14-nist-sp-800-53', '', 128, 'Impact analyses include reviewing security and privacy plans, policies, and procedures to understand control requirements; reviewing system design documentation and operational procedures to understand control implementation and how specific system changes might affect the controls; reviewing the impact of changes on organizational supply chain partners with stakeholders; and determining how potential changes to a system create new risks to the privacy of individuals and the ability of implemented controls to mitigate those risks. Impact analyses also include risk assessments to understand the impact of the changes and determine if additional controls are required.', 'kb-doc-14-nist-sp-800-53-p128-11', 0, 93, '14-nist-sp-800-53', 'retrieved', 'DC4F943FF7EB054674B4D0A3517D8D92CAE590CB3A70A35E9B24508DD1029D98', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p128-12', 'doc-14-nist-sp-800-53', '', 128, 'Related Controls: CA-7, CM-3, CM-8, CM-9, MA-2, RA-3, RA-5, RA-8, SA-5, SA-8, SA-10, SI-2.', 'kb-doc-14-nist-sp-800-53-p128-12', 0, 14, '14-nist-sp-800-53', 'retrieved', '2AEED5947C648CED5A817FD46B2A35AA678E8CC414F25A6CC5C0E2EDEFA17A4D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
