VALUES ('doc-14-nist-sp-800-53-p129-1', 'doc-14-nist-sp-800-53', '', 129, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 102 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p129-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '1F03EBAA9A2C03F54EAC2F480AF4C19262C772C4511EE7AACA7D37914360CC0D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
