INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p129-2', 'doc-14-nist-sp-800-53', '', 129, 'After system changes, verify that the impacted controls are implemented correctly, operating as intended, and producing the desired outcome with regard to meeting the security and privacy requirements for the system.', 'kb-doc-14-nist-sp-800-53-p129-2', 0, 31, '14-nist-sp-800-53', 'retrieved', 'C242B9B3186757939D6FB9F6FE437070BD755BCB358BA91BC5B361325169F841', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
