INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p129-3', 'doc-14-nist-sp-800-53', '', 129, 'Discussion: Implementation in this context refers to installing changed code in the operational system that may have an impact on security or privacy controls.', 'kb-doc-14-nist-sp-800-53-p129-3', 0, 24, '14-nist-sp-800-53', 'retrieved', '99F9E37616FB5155946D6EC21991425B96A67D6F34B4DC4CEDBEBA0DC2DC9C16', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
