INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p129-6', 'doc-14-nist-sp-800-53', '', 129, 'CM-5 ACCESS RESTRICTIONS FOR CHANGE Control: Define, document, approve, and enforce physical and logical access restrictions associated with changes to the system.', 'kb-doc-14-nist-sp-800-53-p129-6', 0, 22, '14-nist-sp-800-53', 'retrieved', '01ACB68CFF3FA445C96F99F33B135DFC73BBC5A4E7D78AF11E5E4013F6F336F8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p129-7', 'doc-14-nist-sp-800-53', '', 129, 'Discussion: Changes to the hardware, software, or firmware components of systems or the operational procedures related to the system can potentially have significant effects on the security of the systems or individuals’ privacy. Therefore, organizations permit only qualified and authorized individuals to access systems for purposes of initiating changes. Access restrictions include physical and logical access controls (see AC-3 and PE-3), software libraries, workflow automation, media libraries, abstract layers (i.e., changes implemented into external interfaces rather than directly into systems), and change windows (i.e., changes occur only during specified times).', 'kb-doc-14-nist-sp-800-53-p129-7', 0, 90, '14-nist-sp-800-53', 'retrieved', 'A6FB4E65CEE773DB4C7A20E4DC8C0C51B9A4E9B49851C98167C3642A9D81A6F4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
