INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p129-10', 'doc-14-nist-sp-800-53', '', 129, 'Discussion: Organizations log system accesses associated with applying configuration changes to ensure that configuration change control is implemented and to support after- the-fact actions should organizations discover any unauthorized changes.', 'kb-doc-14-nist-sp-800-53-p129-10', 0, 30, '14-nist-sp-800-53', 'retrieved', '7588D4AA401F4395D2E81D9072CE2435DD766BED8446DD09A54054FCE7EE726D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
