INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p129-12', 'doc-14-nist-sp-800-53', '', 129, '(2) ACCESS RESTRICTIONS FOR CHANGE | REVIEW SYSTEM CHANGES [Withdrawn: Incorporated into CM-3(7).] (3) ACCESS RESTRICTIONS FOR CHANGE | SIGNED COMPONENTS [Withdrawn: Moved to CM-14.] (4) ACCESS RESTRICTIONS FOR CHANGE | DUAL AUTHORIZATION Enforce dual authorization for implementing changes to [Assignment: organization- defined system components and system-level information].', 'kb-doc-14-nist-sp-800-53-p129-12', 0, 48, '14-nist-sp-800-53', 'retrieved', '63C2CDADB36E76CDB63540495BE8799B9FF0E837233D3349A957CF2077777882', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
