VALUES ('doc-14-nist-sp-800-53-p130-1', 'doc-14-nist-sp-800-53', '', 130, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 103 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p130-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '772DF60FC8C319E778B9BA884899EA9F9102AE27D8FF887F2EBAEC7F95DBA936', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
