INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p130-2', 'doc-14-nist-sp-800-53', '', 130, '(5) ACCESS RESTRICTIONS FOR CHANGE | PRIVILEGE LIMITATION FOR PRODUCTION AND OPERATION (a) Limit privileges to change system components and system-related information within a production or operational environment; and (b) Review and reevaluate privileges [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p130-2', 0, 37, '14-nist-sp-800-53', 'retrieved', '658DAB4C3EFD60F650D1006A6C441A966D2E2A889D65F39EF7C8F0870F0490CE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
