INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p130-3', 'doc-14-nist-sp-800-53', '', 130, 'Discussion: In many organizations, systems support multiple mission and business functions.', 'kb-doc-14-nist-sp-800-53-p130-3', 0, 11, '14-nist-sp-800-53', 'retrieved', 'BC396F59A89B529E2B748A54A1F506A91017025936127EB0DC138E72AF782285', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
