INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p130-4', 'doc-14-nist-sp-800-53', '', 130, 'Limiting privileges to change system components with respect to operational systems is necessary because changes to a system component may have far-reaching effects on mission and business processes supported by the system. The relationships between systems and mission/business processes are, in some cases, unknown to developers. System-related information includes operational procedures.', 'kb-doc-14-nist-sp-800-53-p130-4', 0, 51, '14-nist-sp-800-53', 'retrieved', 'F143D09B6293601F62278ECD22A91DBCF58123F22640368522F69E03F252DFBF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
