VALUES ('doc-14-nist-sp-800-53-p130-9', 'doc-14-nist-sp-800-53', '', 130, '(7) ACCESS RESTRICTIONS FOR CHANGE | AUTOMATIC IMPLEMENTATION OF SECURITY SAFEGUARDS [Withdrawn: Incorporated into SI-7.] References: [FIPS 140-3]; [FIPS 186-4].', 'kb-doc-14-nist-sp-800-53-p130-9', 0, 20, '14-nist-sp-800-53', 'retrieved', '4D1357CB477615A3ED7D1FBA159DBDAEF3C3A1B931944DE7861461A80115057C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
