VALUES ('doc-14-nist-sp-800-53-p131-1', 'doc-14-nist-sp-800-53', '', 131, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 104 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p131-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '2A5C9B6F988B76B71B01A2452D6DDEED9747534506DC5AB09D0F3082E6E09AE8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
