INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p131-7', 'doc-14-nist-sp-800-53', '', 131, 'Automation can also provide data aggregation and data correlation capabilities, alerting mechanisms, and dashboards to support risk-based decision-making within the organization.', 'kb-doc-14-nist-sp-800-53-p131-7', 0, 21, '14-nist-sp-800-53', 'retrieved', '4030031B353979C21926C3BBC93702187D3B5ECB43282EE4876BE21BA05192ED', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
