INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p131-9', 'doc-14-nist-sp-800-53', '', 131, '(2) CONFIGURATION SETTINGS | RESPOND TO UNAUTHORIZED CHANGES Take the following actions in response to unauthorized changes to [Assignment: organization-defined configuration settings]: [Assignment: organization-defined actions].', 'kb-doc-14-nist-sp-800-53-p131-9', 0, 25, '14-nist-sp-800-53', 'retrieved', 'BBEB503F09351473B7952F1A84EEC8969FC8FCE4CB47CE4304CF534080AA6B39', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
