INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p131-10', 'doc-14-nist-sp-800-53', '', 131, 'Discussion: Responses to unauthorized changes to configuration settings include alerting designated organizational personnel, restoring established configuration settings, or— in extreme cases— halting affected system processing.', 'kb-doc-14-nist-sp-800-53-p131-10', 0, 25, '14-nist-sp-800-53', 'retrieved', 'F65B8540C756F2F3FBE8A079765DA9E0E03D626623F86245C7414C6A5D8B6F24', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
