INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p131-12', 'doc-14-nist-sp-800-53', '', 131, '(3) CONFIGURATION SETTINGS | UNAUTHORIZED CHANGE DETECTION [Withdrawn: Incorporated into SI-7.] (4) CONFIGURATION SETTINGS | CONFORMANCE DEMONSTRATION [Withdrawn: Incorporated into CM-4.] References: [SP 800-70], [SP 800-126], [SP 800-128], [USGCB], [NCPR], [DOD STIG].', 'kb-doc-14-nist-sp-800-53-p131-12', 0, 32, '14-nist-sp-800-53', 'retrieved', '81BBD43F1D92693F5595CEDA3957AA6B52FAC048D101102FAFE3267808B240EA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
