INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p134-2', 'doc-14-nist-sp-800-53', '', 134, 'Allow execution of binary or machine-executable code only in confined physical or virtual machine environments and with the explicit approval of [Assignment: organization- defined personnel or roles] when such code is: (a) Obtained from sources with limited or no warranty; and/or (b) Without the provision of source code.', 'kb-doc-14-nist-sp-800-53-p134-2', 0, 48, '14-nist-sp-800-53', 'retrieved', '7F127EDDB0D204E640058778865832CDFD31497EC4FF9D41BE84F548E87B445C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
