INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p134-3', 'doc-14-nist-sp-800-53', '', 134, 'Discussion: Code execution in protected environments applies to all sources of binary or machine-executable code, including commercial software and firmware and open-source software.', 'kb-doc-14-nist-sp-800-53-p134-3', 0, 23, '14-nist-sp-800-53', 'retrieved', '2CF4393FDDA4031A7A36081699CB883B143681354D8DD1A3799E029278816D42', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
