INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p134-5', 'doc-14-nist-sp-800-53', '', 134, '(8) LEAST FUNCTIONALITY | BINARY OR MACHINE EXECUTABLE CODE (a) Prohibit the use of binary or machine-executable code from sources with limited or no warranty or without the provision of source code; and (b) Allow exceptions only for compelling mission or operational requirements and with the approval of the authorizing official.', 'kb-doc-14-nist-sp-800-53-p134-5', 0, 51, '14-nist-sp-800-53', 'retrieved', '3A5E916A4B90A7EB9178A985140221BD249CD6D8118CE3C3589D22FCE997CCE1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
